/* SQLP (SQL 전문가) — 실전 모의고사 (72문항 · 180분 · 100점)
   구성: 객관식 70문항 × 1점 + 서술형 2문항 × 15점
     1과목 데이터 모델링의 이해 10 · 2과목 SQL 기본 및 활용 20
     3과목 SQL 고급 활용 및 튜닝 40 + 서술형 2
   합격: 총점 75점 이상 · 과목별 배점의 40% 이상 (과락 4 / 8 / 28점)
   ─ 특정 회차의 기출이 아니라 SQL 전문가 가이드의 출제 범위와 난이도를 기준으로 작성했습니다.
   엔진(assets/exam-engine.js)이 window.EXAMS 로 읽습니다. */
window.EXAMS = [];
const EXAMS = window.EXAMS;

EXAMS.push({title:"제1회 실전 모의고사",note:"실행계획·조인·인덱스 튜닝 비중 그대로",q:[

/* ============ 1과목 · 데이터 모델링의 이해 (10) ============ */
{n:1,s:1,q:"정규화와 성능에 대한 설명으로 가장 적절한 것은?",o:["정규화를 수행하면 항상 조회 성능이 향상된다","정규화는 데이터 중복을 줄여 입력·수정·삭제 성능을 높이지만 조인 증가로 조회 성능이 나빠질 수 있다","반정규화는 데이터 무결성을 높이기 위해 수행한다","정규화 수준이 높을수록 테이블 수가 줄어든다"],a:1,e:"정규화는 중복 제거로 DML 성능과 무결성에 유리하지만 조인이 늘어 조회 성능이 떨어질 수 있고, 이때 선택적으로 반정규화를 검토합니다."},
{n:2,s:1,q:"다음 중 반정규화를 검토할 상황으로 보기 어려운 것은?",o:["대량의 조인이 반복되어 조회 성능이 임계치를 넘은 경우","통계성 집계를 매번 계산해야 하는 경우","특정 컬럼의 값이 자주 변경되어 갱신 이상이 우려되는 경우","이력 테이블에서 최신 데이터만 반복 조회하는 경우"],a:2,e:"갱신 이상이 우려되면 오히려 정규화가 답입니다. 반정규화는 조회 성능을 얻는 대신 중복 관리 부담을 지는 선택입니다."},
{n:3,s:1,q:"식별자 관계와 비식별자 관계에 대한 설명으로 올바르지 않은 것은?",o:["식별자 관계는 부모의 주식별자를 자식의 주식별자에 포함시킨다","식별자 관계가 이어지면 자식의 주식별자 컬럼 수가 늘어나 조인 복잡도가 증가한다","비식별자 관계는 부모의 식별자를 자식의 일반 속성으로 받으며 NULL이 허용될 수 있다","비식별자 관계를 남용하면 SQL 조인 경로가 짧아져 성능이 좋아진다"],a:3,e:"비식별자 관계를 남용하면 조인 경로가 오히려 길어지고 부모 키가 전달되지 않아 불필요한 조인이 생깁니다. 두 관계는 업무 성격과 조인 편의성을 함께 보고 선택합니다."},
{n:4,s:1,q:"슈퍼타입·서브타입 모델을 물리 모델로 변환하는 방식 중, 서브타입별로 테이블을 분리하는 방식의 특징으로 옳은 것은?",o:["전체 조회 시 UNION ALL이 필요해 불리하다","저장 공간 낭비가 가장 크다","트랜잭션이 항상 슈퍼타입 전체를 대상으로 할 때 유리하다","서브타입 구분 컬럼이 반드시 필요하다"],a:0,e:"서브타입별 분리(Plus 또는 OneToOne 방식)는 개별 서브타입 처리에는 유리하지만 전체를 보려면 UNION ALL이 필요합니다. 전체 대상 트랜잭션이 많으면 단일 테이블(All in One)이 유리합니다."},
{n:5,s:1,q:"분산 데이터베이스의 투명성(Transparency)에 해당하지 않는 것은?",o:["분할 투명성","위치 투명성","중복 투명성","정규화 투명성"],a:3,e:"분산 데이터베이스의 투명성은 분할·위치·지역사상·중복·장애·병행 투명성입니다."},
{n:6,s:1,q:"릴레이션 R(A, B, C)에서 A→B, B→C 가 성립하고 A가 유일한 후보키일 때, 이 릴레이션이 위배하는 정규형은?",o:["제1정규형","제2정규형","제3정규형","BCNF"],a:2,e:"A→B→C 의 이행 함수 종속이 존재하므로 제3정규형을 위배합니다. 후보키가 단일 속성이라 부분 함수 종속은 발생하지 않습니다."},
{n:7,s:1,q:"선분 이력(기간 이력) 모델에 대한 설명으로 옳지 않은 것은?",o:["시작일자와 종료일자로 유효 기간을 표현한다","특정 시점의 데이터를 조회할 때 BETWEEN 조건을 사용할 수 있다","최신 행의 종료일자를 '99991231' 같은 최대값으로 두면 최신 조회가 단순해진다","점 이력(발생 이력) 방식보다 항상 저장 공간을 적게 쓴다"],a:3,e:"선분 이력은 종료일자 컬럼이 추가되므로 저장 공간은 더 쓰지만, 시점 조회 SQL이 단순해지고 성능이 좋아집니다."},
{n:8,s:1,q:"M:M(다대다) 관계를 물리 모델로 전개할 때 필요한 조치는?",o:["두 엔터티를 하나로 통합한다","연결(교차) 엔터티를 생성해 1:M 관계 두 개로 분해한다","한쪽 엔터티의 식별자를 다중값 속성으로 저장한다","관계를 삭제하고 애플리케이션에서 처리한다"],a:1,e:"연결 엔터티에 양쪽 식별자를 외래키로 두고 이를 주식별자로 삼는 것이 일반적입니다."},
{n:9,s:1,q:"NULL을 허용하는 선택 속성 설계가 SQL 성능에 미치는 영향으로 옳은 것은?",o:["NULL이 많은 컬럼은 B*Tree 인덱스에 저장되지 않아 인덱스만으로 전체 건수를 셀 수 없다","NULL은 인덱스에 0으로 저장되므로 문제가 없다","NULL 컬럼은 항상 인덱스 선두 컬럼으로 적합하다","NULL은 COUNT(*)에서 제외된다"],a:0,e:"단일 컬럼 B*Tree 인덱스는 NULL을 저장하지 않으므로 IS NULL 조건은 인덱스를 타지 못하고, 인덱스 풀 스캔으로 전체 건수를 세는 것도 불가능합니다. COUNT(*)는 NULL을 포함합니다."},
{n:10,s:1,q:"데이터 모델의 3요소에 해당하지 않는 것은?",o:["구조(Structure)","연산(Operation)","제약조건(Constraint)","인덱스(Index)"],a:3,e:"데이터 모델은 구조·연산·제약조건으로 구성됩니다. 인덱스는 물리 설계 산출물입니다."},

/* ============ 2과목 · SQL 기본 및 활용 (20) ============ */
{n:11,s:2,q:"SQL 문장의 논리적 수행 순서로 옳은 것은?",o:["SELECT → FROM → WHERE → GROUP BY → HAVING → ORDER BY","FROM → WHERE → GROUP BY → HAVING → SELECT → ORDER BY","FROM → GROUP BY → WHERE → HAVING → SELECT → ORDER BY","WHERE → FROM → GROUP BY → SELECT → HAVING → ORDER BY"],a:1,e:"SELECT가 HAVING 뒤에 수행되므로 WHERE에서는 SELECT 별칭을 쓸 수 없고 ORDER BY에서는 쓸 수 있습니다."},
{n:12,s:2,q:"다음 중 조인 결과 행 수가 가장 많아질 가능성이 큰 것은?",o:["INNER JOIN","LEFT OUTER JOIN","FULL OUTER JOIN","CROSS JOIN"],a:3,e:"CROSS JOIN(카티션 프로덕트)은 양쪽 행 수의 곱만큼 결과가 나옵니다."},
{n:13,s:2,q:"다음 식의 결과가 올바르지 않은 것은?",code:"(1) NVL(NULL, 'A')          = 'A'\n(2) NULLIF(10, 10)          = NULL\n(3) COALESCE(NULL, NULL, 3) = 3\n(4) NVL2(NULL, 'X', 'Y')    = 'X'",o:["(1)","(2)","(3)","(4)"],a:3,e:"NVL2(expr, v1, v2)는 expr이 NULL이 아니면 v1, NULL이면 v2를 반환하므로 NVL2(NULL,'X','Y')는 'Y'입니다."},
{n:14,s:2,q:"WHERE절과 HAVING절에 대한 설명으로 옳지 않은 것은?",o:["WHERE는 그룹핑 전에 개별 행을 걸러 낸다","HAVING은 그룹핑 후 그룹 단위로 조건을 적용한다","WHERE절에는 집계 함수를 직접 쓸 수 없다","성능상 HAVING으로 먼저 걸러 내는 것이 WHERE보다 유리하다"],a:3,e:"WHERE로 먼저 행을 줄여야 그룹핑 대상이 줄어 성능에 유리합니다."},
{n:15,s:2,q:"GROUP BY ROLLUP(A, B) 가 생성하는 소계 조합으로 옳은 것은?",o:["(A,B), (A), ()","(A,B), (A), (B), ()","(A,B), (B), ()","(A,B) 만"],a:0,e:"ROLLUP은 오른쪽부터 하나씩 제거하며 계층적 소계를 만듭니다. 모든 조합은 CUBE입니다."},
{n:16,s:2,q:"동일한 값에 대해 같은 순위를 부여하고 다음 순위를 건너뛰지 않는 윈도우 함수는?",o:["RANK()","DENSE_RANK()","ROW_NUMBER()","NTILE()"],a:1,e:"RANK는 1,1,3처럼 건너뛰고 DENSE_RANK는 1,1,2로 이어집니다. ROW_NUMBER는 동일 값에도 고유 번호를 매깁니다."},
{n:17,s:2,q:"직전 행의 값을 현재 행에 함께 조회하려 할 때 사용하는 함수는?",o:["LAG","LEAD","FIRST_VALUE","NTILE"],a:0,e:"LAG는 이전 행, LEAD는 다음 행의 값을 가져옵니다."},
{n:18,s:2,q:"계층형 질의에서 루트로부터의 깊이를 반환하는 의사 컬럼은?",o:["LEVEL","ROWNUM","CONNECT_BY_ISLEAF","SYS_CONNECT_BY_PATH"],a:0,e:"LEVEL은 루트가 1이며 자식으로 갈수록 1씩 증가합니다."},
{n:19,s:2,q:"인라인 뷰(Inline View)에 대한 설명으로 옳은 것은?",o:["FROM절에 사용하는 서브쿼리이다","SELECT절에 한 건만 반환하는 서브쿼리이다","WHERE절에서 메인 쿼리 컬럼을 참조하는 서브쿼리이다","반드시 뷰로 생성해 두어야 사용할 수 있다"],a:0,e:"SELECT절의 것은 스칼라 서브쿼리, 메인 컬럼을 참조하면 상관 서브쿼리입니다."},
{n:20,s:2,q:"IN과 EXISTS에 대한 설명으로 가장 적절한 것은?",o:["EXISTS는 조건을 만족하는 행을 하나 찾으면 즉시 참으로 판단한다","IN은 항상 EXISTS보다 빠르다","EXISTS는 서브쿼리의 SELECT 목록 값을 비교에 사용한다","두 연산자는 NULL 처리 방식이 완전히 동일하다"],a:0,e:"EXISTS는 존재 여부만 확인하므로 첫 행을 찾는 즉시 종료합니다. NOT IN은 서브쿼리에 NULL이 있으면 결과가 공집합이 되는 함정이 있습니다."},
{n:21,s:2,q:"두 집합의 중복을 제거하지 않고 그대로 결합하며 정렬 부하가 없는 집합 연산자는?",o:["UNION","UNION ALL","INTERSECT","MINUS"],a:1,e:"UNION은 중복 제거를 위해 정렬(또는 해시) 작업이 필요하지만 UNION ALL은 그대로 붙이므로 부하가 적습니다."},
{n:22,s:2,q:"소스 데이터의 존재 여부에 따라 UPDATE와 INSERT를 한 문장으로 처리하는 SQL은?",o:["MERGE","UPSERT","REPLACE","UPDATE OR INSERT"],a:0,e:"MERGE INTO ... USING ... ON ... WHEN MATCHED THEN UPDATE WHEN NOT MATCHED THEN INSERT 구조입니다."},
{n:23,s:2,q:"트랜잭션 제어어(TCL)에 해당하지 않는 것은?",o:["COMMIT","ROLLBACK","SAVEPOINT","TRUNCATE"],a:3,e:"TRUNCATE는 DDL이며 자동 커밋되어 롤백할 수 없습니다."},
{n:24,s:2,q:"여러 사용자에게 동일한 권한 묶음을 부여할 때 사용하는 객체는?",o:["ROLE","SYNONYM","SEQUENCE","VIEW"],a:0,e:"ROLE에 권한을 모아 두고 사용자에게 롤을 부여하면 권한 관리가 단순해집니다."},
{n:25,s:2,q:"뷰(View)의 특징으로 옳지 않은 것은?",o:["복잡한 SQL을 단순화할 수 있다","특정 컬럼만 노출해 보안을 강화할 수 있다","독립적인 저장 공간을 차지하여 조회 성능이 항상 향상된다","기본 테이블의 구조가 바뀌어도 뷰를 사용하는 SQL은 영향을 덜 받는다"],a:2,e:"일반 뷰는 SQL 정의만 저장하므로 별도 저장 공간을 갖지 않습니다. 실제 데이터를 저장하는 것은 구체화 뷰(Materialized View)입니다."},
{n:26,s:2,q:"UNIQUE 제약조건과 UNIQUE 인덱스에 대한 설명으로 옳은 것은?",o:["UNIQUE 제약조건을 만들면 내부적으로 유니크 인덱스가 생성된다","UNIQUE 인덱스는 NULL을 허용하지 않는다","기본키에는 인덱스가 생성되지 않는다","UNIQUE 제약조건은 인덱스와 무관하게 동작한다"],a:0,e:"UNIQUE·PRIMARY KEY 제약을 걸면 이를 강제하기 위한 유니크 인덱스가 만들어집니다. 유니크 인덱스도 NULL은 여러 건 허용됩니다."},
{n:27,s:2,q:"다음 함수의 결과가 올바르지 않은 것은?",code:"(1) SUBSTR('SQLP2026', 5, 4)  = '2026'\n(2) INSTR('SQLP2026', 'P')    = 4\n(3) LTRIM('xxSQL', 'x')       = 'SQL'\n(4) REPLACE('SQLP', 'P', '')  = 'SQLP'",o:["(1)","(2)","(3)","(4)"],a:3,e:"REPLACE('SQLP','P','')는 'P'를 빈 문자열로 바꾸므로 'SQL'이 됩니다."},
{n:28,s:2,q:"날짜 연산에 대한 설명으로 옳지 않은 것은?",o:["DATE 타입에서 날짜끼리 빼면 일수(숫자)가 반환된다","SYSDATE + 1 은 하루 뒤를 의미한다","MONTHS_BETWEEN은 두 날짜 사이의 개월 수를 반환한다","TO_CHAR(SYSDATE,'YYYYMMDD')의 결과는 DATE 타입이다"],a:3,e:"TO_CHAR의 결과는 문자열(VARCHAR2)입니다."},
{n:29,s:2,q:"CASE 표현식과 DECODE 함수의 차이로 옳은 것은?",o:["DECODE는 등가(=) 비교만 가능하지만 CASE는 범위 조건도 쓸 수 있다","CASE는 Oracle 전용이다","DECODE는 ELSE를 지정할 수 없다","둘 다 ANSI 표준 함수이다"],a:0,e:"DECODE는 Oracle 전용의 등가 비교 함수이고, CASE는 ANSI 표준이며 BETWEEN·부등호 같은 조건도 사용할 수 있습니다."},
{n:30,s:2,q:"행으로 저장된 값을 열로 전환하여 집계 결과를 가로로 펼칠 때 사용할 수 있는 것은?",o:["PIVOT 또는 CASE + 집계 함수","CONNECT BY","MERGE","ROWNUM"],a:0,e:"PIVOT 절을 쓰거나 SUM(CASE WHEN 조건 THEN 값 END) 형태로 구현합니다."},

/* ============ 3과목 · SQL 고급 활용 및 튜닝 (40 + 서술 2) ============ */
{n:31,s:3,q:"비용 기반 옵티마이저(CBO)에 대한 설명으로 옳지 않은 것은?",o:["통계 정보를 이용해 실행 계획의 비용을 추정한다","동일한 SQL이라도 통계가 바뀌면 실행 계획이 달라질 수 있다","규칙에 정해진 우선순위만으로 계획을 결정한다","카디널리티 추정 오차가 잘못된 조인 순서를 유발할 수 있다"],a:2,e:"규칙의 우선순위로 결정하는 것은 규칙 기반 옵티마이저(RBO)입니다."},
{n:32,s:3,q:"실행 계획을 읽는 순서로 옳은 것은?",o:["위에서 아래로 순서대로 읽는다","들여쓰기가 가장 깊은 단계부터, 같은 깊이에서는 위에서 아래로 읽는다","아래에서 위로만 읽는다","ID 번호가 큰 것부터 읽는다"],a:1,e:"자식 오퍼레이션이 먼저 수행되므로 가장 안쪽(들여쓰기가 깊은) 단계부터, 형제 간에는 위에서 아래로 읽습니다."},
{n:33,s:3,q:"옵티마이저 통계 정보에 포함되지 않는 것은?",o:["테이블의 행 수와 블록 수","컬럼의 distinct 값 개수와 히스토그램","인덱스의 높이와 클러스터링 팩터","SQL의 하드 파싱 횟수"],a:3,e:"파싱 횟수는 라이브러리 캐시 통계이지 옵티마이저가 비용 추정에 쓰는 오브젝트 통계가 아닙니다."},
{n:34,s:3,q:"B*Tree 인덱스의 구조에 대한 설명으로 옳지 않은 것은?",o:["루트·브랜치·리프 블록의 계층 구조를 갖는다","리프 블록은 키 값 순으로 정렬되어 있고 양방향 연결 리스트로 이어져 있다","모든 리프 블록의 깊이가 동일하다","키 값이 없는(NULL) 행도 단일 컬럼 인덱스에 저장된다"],a:3,e:"단일 컬럼 B*Tree 인덱스는 NULL을 저장하지 않습니다. 그래서 IS NULL 조건은 해당 인덱스를 사용할 수 없습니다."},
{n:35,s:3,q:"인덱스 범위 스캔(Index Range Scan)이 테이블 풀 스캔보다 불리해지는 대표적인 상황은?",o:["조건을 만족하는 행이 전체의 극히 일부일 때","조건을 만족하는 행이 전체의 상당 비율을 차지할 때","인덱스 선두 컬럼이 등치 조건일 때","결과를 인덱스 정렬 순서로 반환해야 할 때"],a:1,e:"추출 건수가 많으면 테이블 랜덤 액세스가 폭증해, 순차적으로 읽는 풀 스캔이 오히려 유리해집니다."},
{n:36,s:3,q:"인덱스 고유 스캔(Index Unique Scan)이 발생하는 조건은?",o:["유니크 인덱스의 전체 컬럼에 등치(=) 조건이 주어진 경우","비유니크 인덱스에 범위 조건이 주어진 경우","인덱스 선두 컬럼이 조건에서 빠진 경우","ORDER BY 만 존재하는 경우"],a:0,e:"유니크 인덱스 구성 컬럼 전체가 = 조건이면 최대 한 건이므로 고유 스캔이 됩니다."},
{n:37,s:3,q:"인덱스 스킵 스캔(Index Skip Scan)이 효과적인 경우는?",o:["선두 컬럼의 distinct 값이 매우 적고 후행 컬럼에 조건이 있는 경우","선두 컬럼의 distinct 값이 매우 많은 경우","인덱스가 단일 컬럼으로 구성된 경우","조건절이 전혀 없는 경우"],a:0,e:"선두 컬럼의 값 종류가 적으면 값마다 서브 인덱스를 건너뛰며 탐색하는 것이 풀 스캔보다 유리할 수 있습니다."},
{n:38,s:3,q:"Index Full Scan과 Index Fast Full Scan의 차이로 옳은 것은?",o:["Fast Full Scan은 인덱스 정렬 순서를 보장하지 않지만 멀티블록 I/O로 빠르게 읽는다","Full Scan이 항상 더 빠르다","Fast Full Scan은 테이블 액세스가 반드시 필요하다","두 방식 모두 정렬 순서를 보장한다"],a:0,e:"Fast Full Scan은 인덱스 세그먼트를 통째로 멀티블록 읽기 하므로 순서가 보장되지 않고, 필요한 컬럼이 인덱스에 모두 있을 때 쓸 수 있습니다."},
{n:39,s:3,q:"결합 인덱스 (A, B, C) 가 있을 때 인덱스 스캔 범위를 가장 효과적으로 줄이는 조건절은?",o:["A = :a AND B = :b AND C = :c","A = :a AND C = :c","B = :b AND C = :c","C = :c"],a:0,e:"선두 컬럼부터 연속으로 등치 조건이 주어질수록 스캔 시작·종료 지점이 좁아집니다. 선두 컬럼이 빠지면 범위를 좁히지 못합니다."},
{n:40,s:3,q:"결합 인덱스 컬럼 순서를 정할 때 가장 우선해야 할 기준은?",o:["항상 = 조건으로 사용되는 컬럼을 앞쪽에 둔다","distinct 값이 적은 컬럼을 무조건 앞에 둔다","컬럼 이름의 알파벳 순으로 둔다","데이터 타입 크기가 작은 컬럼을 앞에 둔다"],a:0,e:"등치 조건 컬럼을 선두에 두어야 스캔 시작점이 확정되고 범위가 최소화됩니다. 범위 조건 컬럼은 뒤로 보냅니다."},
{n:41,s:3,q:"다음 중 인덱스를 정상적으로 사용할 수 있는 조건절은?",o:["WHERE SUBSTR(CUST_NM, 1, 3) = '홍길동'","WHERE SALE_AMT * 1.1 > 10000","WHERE TO_CHAR(ORD_DT, 'YYYYMMDD') = '20260824'","WHERE ORD_DT >= TO_DATE('20260824','YYYYMMDD')"],a:3,e:"인덱스 컬럼을 가공하면 인덱스를 사용할 수 없습니다. 가공은 상수 쪽으로 옮겨야 합니다."},
{n:42,s:3,q:"문자형 컬럼에 숫자 값을 조건으로 주었을 때 발생하는 묵시적 형변환의 영향으로 옳은 것은?",o:["컬럼 쪽에 TO_NUMBER가 적용되어 인덱스를 사용할 수 없게 된다","상수 쪽만 변환되므로 성능에 영향이 없다","항상 에러가 발생한다","인덱스 스킵 스캔으로 자동 전환된다"],a:0,e:"WHERE 문자컬럼 = 100 처럼 쓰면 컬럼이 가공되어 인덱스가 무력화됩니다. 상수를 문자로 넘겨야 합니다."},
{n:43,s:3,q:"클러스터링 팩터(Clustering Factor)에 대한 설명으로 옳은 것은?",o:["인덱스 키 순서와 테이블 저장 순서가 비슷할수록 값이 작고 랜덤 액세스 비용이 낮다","값이 클수록 인덱스 효율이 좋다","인덱스의 높이를 의미한다","테이블 행 수와 항상 동일하다"],a:0,e:"클러스터링 팩터가 좋으면 같은 블록을 반복해 읽으므로 테이블 랜덤 액세스 비용이 크게 줄어듭니다."},
{n:44,s:3,q:"테이블 랜덤 액세스 부하를 줄이는 방법으로 가장 효과적인 것은?",o:["SELECT 절에 필요한 컬럼을 인덱스에 모두 포함시켜 커버링 인덱스를 만든다","인덱스를 삭제한다","힌트로 조인 순서를 고정한다","커밋 주기를 늘린다"],a:0,e:"필요한 컬럼이 인덱스에 모두 있으면 테이블 액세스 없이 인덱스만 읽고 끝낼 수 있습니다."},
{n:45,s:3,q:"부분 범위 처리(Partial Range Scan)가 성립하기 위한 조건으로 옳은 것은?",o:["결과를 전량 가공하지 않고 앞쪽 일부만 필요하며 정렬·집계로 전체를 읽지 않아도 되는 경우","반드시 GROUP BY가 있어야 한다","ORDER BY를 정렬 연산으로 수행해야 한다","항상 테이블 풀 스캔이어야 한다"],a:0,e:"소트나 전체 집계가 개입하면 전체 범위를 다 읽어야 하므로 부분 범위 처리가 깨집니다. 인덱스로 소트를 대체하면 유지할 수 있습니다."},
{n:46,s:3,q:"NL(Nested Loop) 조인에 대한 설명으로 옳지 않은 것은?",o:["선행 테이블의 각 행마다 후행 테이블을 반복 탐색한다","후행 테이블의 조인 컬럼에 인덱스가 있어야 효율적이다","대량 데이터를 조인할 때 가장 유리하다","부분 범위 처리가 가능해 온라인 트랜잭션에 적합하다"],a:2,e:"대량 조인은 랜덤 액세스가 폭증하므로 해시 조인이나 소트 머지 조인이 유리합니다."},
{n:47,s:3,q:"Sort Merge 조인이 유리한 상황은?",o:["조인 컬럼에 인덱스가 없고 부등호(비등가) 조인 조건인 경우","소량 데이터를 인덱스로 빠르게 찾는 경우","해시 함수를 적용할 메모리가 충분한 등치 조인","선행 테이블이 한 건인 경우"],a:0,e:"해시 조인은 등치(=) 조인만 가능하므로, 비등가 조인이면서 인덱스가 없다면 소트 머지 조인이 대안이 됩니다."},
{n:48,s:3,q:"해시 조인에 대한 설명으로 옳지 않은 것은?",o:["작은 쪽 집합으로 해시 테이블을 만들어 큰 쪽을 탐색한다","등치(=) 조인 조건에서만 사용할 수 있다","해시 테이블이 메모리에 다 올라가지 않으면 디스크에 쓰는 부하가 생긴다","조인 컬럼에 인덱스가 반드시 필요하다"],a:3,e:"해시 조인은 인덱스가 없어도 동작하며, 대량 데이터 조인에 강합니다."},
{n:49,s:3,q:"NL 조인에서 드라이빙(선행) 테이블 선택 기준으로 가장 적절한 것은?",o:["조건절 적용 후 결과 건수가 적은 쪽","테이블 전체 행 수가 많은 쪽","인덱스가 없는 쪽","컬럼 수가 많은 쪽"],a:0,e:"선행 집합이 작아야 후행 테이블 탐색 횟수가 줄어듭니다."},
{n:50,s:3,q:"스칼라 서브쿼리의 캐싱(Scalar Subquery Caching)에 대한 설명으로 옳은 것은?",o:["입력 값의 종류가 적을수록 캐시 적중률이 높아 효과가 크다","입력 값이 모두 다를수록 효과가 크다","캐시는 무제한이라 항상 이득이다","캐싱은 해시 조인에서만 동작한다"],a:0,e:"코드성 컬럼처럼 값의 가짓수가 적으면 대부분 캐시에서 처리되어 반복 조회를 크게 줄입니다."},
{n:51,s:3,q:"서브쿼리 Unnesting(비중첩화)의 목적으로 옳은 것은?",o:["서브쿼리를 조인 형태로 변환해 옵티마이저가 조인 순서·방식을 선택할 수 있게 한다","서브쿼리를 반드시 필터 방식으로 고정한다","서브쿼리를 문자열로 치환한다","인덱스를 강제로 생성한다"],a:0,e:"Unnesting이 되면 다양한 조인 전략을 고려할 수 있어 대량 처리 성능이 좋아집니다."},
{n:52,s:3,q:"뷰 머징(View Merging)이 수행되지 못하게 막는 요소가 아닌 것은?",o:["뷰 내부의 GROUP BY","뷰 내부의 DISTINCT","뷰 내부의 ROWNUM","뷰 내부의 단순 WHERE 조건"],a:3,e:"단순 조건만 있는 뷰는 머징이 잘 됩니다. 집계·DISTINCT·ROWNUM·집합 연산 등은 머징을 방해합니다."},
{n:53,s:3,q:"조건절 푸싱(Predicate Pushing)의 효과로 옳은 것은?",o:["바깥 쿼리의 조건을 뷰나 인라인 뷰 안쪽으로 밀어 넣어 미리 데이터를 줄인다","조건을 바깥으로 끌어올려 나중에 적용한다","조건을 삭제해 결과를 늘린다","인덱스를 비활성화한다"],a:0,e:"조건을 안쪽에서 먼저 적용하면 중간 집합이 줄어 이후 조인·정렬 부하가 감소합니다."},
{n:54,s:3,q:"조인 순서를 명시적으로 고정하고 싶을 때 사용하는 힌트는?",o:["LEADING","USE_HASH","INDEX_FFS","PARALLEL"],a:0,e:"LEADING(t1 t2)로 선행 테이블 순서를 지정하고, ORDERED는 FROM절 기재 순서를 따르게 합니다."},
{n:55,s:3,q:"병렬 처리(Parallel Execution)에 대한 설명으로 옳지 않은 것은?",o:["대용량 처리를 여러 프로세스로 분담해 응답 시간을 줄인다","동시 사용자가 많은 OLTP 환경에서 무분별하게 쓰면 자원 경합을 유발한다","항상 직렬 처리보다 총 자원 사용량이 적다","DOP(병렬도) 설정이 과하면 오히려 성능이 나빠질 수 있다"],a:2,e:"병렬 처리는 응답 시간을 줄이는 대신 CPU·메모리·I/O 총 사용량은 늘어납니다."},
{n:56,s:3,q:"주문일자 컬럼을 기준으로 월별 테이블을 나누어 관리하려 할 때 적합한 파티셔닝 방식은?",o:["레인지(Range) 파티셔닝","해시(Hash) 파티셔닝","리스트(List) 파티셔닝","라운드 로빈 파티셔닝"],a:0,e:"날짜·수치의 연속 구간은 레인지 파티셔닝이 적합합니다. 해시는 균등 분산, 리스트는 코드 값 분류에 씁니다."},
{n:57,s:3,q:"파티션 프루닝(Partition Pruning)이 동작하기 위한 조건은?",o:["조건절에 파티션 키가 포함되어 불필요한 파티션을 제외할 수 있어야 한다","파티션 키에 인덱스가 없어야 한다","반드시 병렬 처리를 사용해야 한다","파티션이 하나뿐이어야 한다"],a:0,e:"파티션 키가 조건에 없으면 모든 파티션을 읽게 되어 파티셔닝 효과가 사라집니다."},
{n:58,s:3,q:"ORDER BY로 인한 소트 부하를 없애는 가장 좋은 방법은?",o:["정렬 순서와 일치하는 인덱스를 이용해 인덱스 스캔 순서로 결과를 반환한다","NOSORT 힌트를 준다","ORDER BY를 WHERE로 옮긴다","임시 테이블에 저장한 뒤 다시 읽는다"],a:0,e:"인덱스는 이미 정렬되어 있으므로 소트 오퍼레이션 자체를 생략할 수 있고 부분 범위 처리도 가능해집니다."},
{n:59,s:3,q:"GROUP BY 처리 방식에 대한 설명으로 옳은 것은?",o:["Hash Group By는 결과 정렬을 보장하지 않는다","Sort Group By가 항상 더 빠르다","Hash Group By는 항상 정렬된 결과를 반환한다","GROUP BY는 항상 인덱스를 사용한다"],a:0,e:"Hash Group By는 정렬 없이 해시로 그룹을 만들기 때문에 순서가 보장되지 않습니다. 순서가 필요하면 ORDER BY를 명시해야 합니다."},
{n:60,s:3,q:"불필요한 DISTINCT가 성능에 미치는 영향으로 옳은 것은?",o:["중복 제거를 위한 소트 또는 해시 작업이 추가되어 부하가 늘어난다","옵티마이저가 자동으로 제거하므로 영향이 없다","인덱스 사용을 강제한다","항상 결과 건수를 늘린다"],a:0,e:"조인 설계로 중복을 없앨 수 있다면 DISTINCT를 걷어 내는 것이 낫습니다."},
{n:61,s:3,q:"Top-N 페이징 처리를 효율적으로 구현하는 방법으로 가장 적절한 것은?",o:["ORDER BY와 일치하는 인덱스를 이용해 인라인 뷰에서 ROWNUM으로 조기 종료시킨다","전체를 정렬한 뒤 애플리케이션에서 잘라 낸다","DISTINCT로 중복을 제거한 뒤 전량 전송한다","힌트 없이 해시 조인을 유도한다"],a:0,e:"인덱스로 정렬을 대체하면 필요한 건수만 읽고 멈출 수 있어(Stop Key) 부분 범위 처리가 가능합니다."},
{n:62,s:3,q:"대량 INSERT 시 리두(Redo)와 언두(Undo) 부하를 줄이는 방식은?",o:["Direct Path Insert(APPEND 힌트)를 사용해 버퍼 캐시를 우회하고 HWM 위에 기록한다","한 건씩 INSERT하고 매번 커밋한다","인덱스를 더 많이 만든다","트리거를 추가한다"],a:0,e:"다이렉트 경로 적재는 버퍼 캐시를 거치지 않고 새 블록에 기록해 부하를 줄입니다. 다만 적재 중 해당 테이블은 잠깁니다."},
{n:63,s:3,q:"트랜잭션 격리 수준 중 팬텀 리드(Phantom Read)까지 방지하는 수준은?",o:["READ UNCOMMITTED","READ COMMITTED","REPEATABLE READ","SERIALIZABLE"],a:3,e:"SERIALIZABLE이 가장 엄격하며, REPEATABLE READ는 동일 행의 값 변경은 막지만 새로운 행의 등장은 막지 못합니다."},
{n:64,s:3,q:"블로킹(Blocking)에 대한 설명으로 옳은 것은?",o:["선행 트랜잭션이 잡은 락 때문에 후행 트랜잭션이 대기하는 상태이다","두 트랜잭션이 서로를 무한히 기다리는 상태이다","트랜잭션이 자동으로 롤백되는 현상이다","락이 전혀 발생하지 않는 상태이다"],a:0,e:"서로를 기다려 영원히 풀리지 않는 것은 데드락이며, DBMS가 한쪽을 강제 종료해 해소합니다."},
{n:65,s:3,q:"커밋 주기를 지나치게 짧게(건건이) 가져갈 때 발생하는 문제는?",o:["로그 파일 동기화 대기가 늘어 전체 처리량이 떨어진다","언두 공간을 전혀 쓰지 않는다","락 경합이 완전히 사라진다","리두 로그가 생성되지 않는다"],a:0,e:"커밋마다 로그 파일 쓰기 완료를 기다리므로 잦은 커밋은 오히려 성능을 떨어뜨립니다. 반대로 너무 길면 언두 부족과 락 점유가 문제가 됩니다."},
{n:66,s:3,q:"바인드 변수를 사용하는 가장 큰 이유는?",o:["동일한 SQL 커서를 공유해 하드 파싱을 줄이고 라이브러리 캐시 경합을 완화한다","실행 계획을 항상 최적으로 만든다","인덱스를 자동 생성한다","통계 정보를 갱신한다"],a:0,e:"리터럴 SQL은 값마다 다른 SQL로 인식되어 매번 하드 파싱과 커서 생성 부하가 발생합니다."},
{n:67,s:3,q:"하드 파싱(Hard Parsing)에 포함되지 않는 단계는?",o:["문법·의미 검사","최적화(실행 계획 생성)","로우 소스 생성","이미 캐시된 실행 계획의 재사용"],a:3,e:"캐시된 계획을 재사용하는 것이 소프트 파싱입니다."},
{n:68,s:3,q:"Array Processing(배열 처리)의 효과로 옳은 것은?",o:["한 번의 데이터베이스 Call로 여러 행을 처리해 네트워크 왕복과 Call 부하를 줄인다","행마다 커밋하여 안정성을 높인다","인덱스를 사용하지 않게 만든다","실행 계획을 고정한다"],a:0,e:"JDBC의 배치 처리나 PL/SQL의 BULK COLLECT / FORALL이 대표적입니다."},
{n:69,s:3,q:"SQL 튜닝에서 가장 먼저 줄여야 할 대상으로 우선순위가 높은 것은?",o:["데이터베이스 Call 횟수와 블록 I/O(특히 랜덤 액세스)","SQL 문장의 글자 수","테이블 컬럼 수","뷰의 개수"],a:0,e:"응답 시간의 대부분은 Call 오버헤드와 블록 I/O에서 발생하므로, 액세스 경로를 줄이는 것이 튜닝의 핵심입니다."},
{n:70,s:3,q:"다음 실행 계획 조각의 해석으로 옳은 것은?",code:"----------------------------------------------------------\n| Id | Operation                    | Name      | Rows |\n----------------------------------------------------------\n|  0 | SELECT STATEMENT             |           |   10 |\n|  1 |  NESTED LOOPS                |           |   10 |\n|  2 |   TABLE ACCESS BY INDEX ROWID| 주문      |   10 |\n|* 3 |    INDEX RANGE SCAN          | 주문_IDX  |   10 |\n|  4 |   TABLE ACCESS BY INDEX ROWID| 고객      |    1 |\n|* 5 |    INDEX UNIQUE SCAN         | 고객_PK   |    1 |\n----------------------------------------------------------",o:["고객 테이블이 선행(드라이빙) 테이블이다","주문 테이블을 인덱스로 먼저 읽고, 그 각 행마다 고객을 PK로 조회한다","해시 조인이 사용되었다","주문 테이블을 풀 스캔한다"],a:1,e:"NESTED LOOPS의 첫 번째 자식(Id 2)이 선행 테이블입니다. 주문을 인덱스 범위 스캔으로 읽고 각 행마다 고객_PK로 고유 스캔합니다."},

{n:71,s:3,t:'desc',pts:15,q:"두 테이블을 조인할 때 NL 조인과 해시 조인 중 무엇을 선택할지 판단하는 기준을 세 가지 이상 들어 서술하시오.",
model:"① 처리 건수 — 선행 집합이 소량이고 부분 범위 처리가 필요한 온라인 조회는 NL 조인이, 양쪽이 대량이고 전체를 가공해야 하는 배치성 작업은 해시 조인이 유리하다. ② 인덱스 유무 — NL 조인은 후행 테이블의 조인 컬럼에 인덱스가 있어야 효율적이며, 없으면 랜덤 액세스가 폭증한다. 해시 조인은 인덱스가 없어도 동작한다. ③ 조인 조건 — 해시 조인은 등치(=) 조인에서만 가능하므로 비등가 조인은 NL 또는 소트 머지 조인을 써야 한다. ④ 메모리 — 해시 조인은 작은 쪽 집합으로 해시 테이블을 만들므로 PGA 메모리가 부족하면 디스크에 쓰는 부하(Temp)가 발생한다. ⑤ 클러스터링 팩터 — NL 조인은 후행 테이블의 클러스터링 팩터가 나쁘면 블록 I/O가 급증한다.",
points:["처리 건수와 부분 범위 처리 필요 여부","후행 테이블 조인 컬럼의 인덱스 유무","등치 조인 여부(해시 조인 제약)","PGA 메모리와 Temp 사용 부담","랜덤 액세스 비용(클러스터링 팩터)"],
e:"'소량·온라인·인덱스 있음 → NL / 대량·배치·등치 조인 → 해시'가 뼈대입니다. 힌트로 USE_NL, USE_HASH를 주더라도 왜 그 선택이 맞는지 설명할 수 있어야 합니다."},

{n:72,s:3,t:'desc',pts:15,q:"아래 SQL이 자주 수행된다. 결합 인덱스를 설계한다면 컬럼을 어떤 순서로 구성해야 하는지, 그 이유와 함께 서술하시오.",
code:"SELECT 주문번호, 주문금액\n  FROM 주문\n WHERE 고객번호 = :cust\n   AND 주문상태 = :stat\n   AND 주문일자 >= :from_dt\n ORDER BY 주문일자 DESC;",
model:"(고객번호, 주문상태, 주문일자) 순서로 구성한다. ① 등치(=) 조건인 고객번호와 주문상태를 선두에 두어야 인덱스 스캔의 시작점과 끝점이 확정되어 스캔 범위가 최소화된다. ② 범위 조건인 주문일자는 그 뒤에 두어야 한다. 범위 조건 컬럼을 앞에 두면 그 뒤 컬럼들은 스캔 범위를 좁히는 데 기여하지 못하고 필터 조건으로만 작동한다. ③ 주문일자를 마지막에 두면 인덱스가 이미 주문일자 순으로 정렬되어 있으므로 ORDER BY 주문일자 DESC를 인덱스 역순 스캔으로 대체할 수 있어 소트 오퍼레이션이 사라지고 부분 범위 처리가 가능해진다. ④ 더 나아가 주문번호와 주문금액까지 인덱스에 포함하면 테이블 랜덤 액세스 없이 인덱스만으로 처리(커버링 인덱스)할 수 있다.",
points:["등치 조건 컬럼(고객번호·주문상태)을 선두에 배치","범위 조건 컬럼(주문일자)을 뒤에 배치하는 이유","ORDER BY를 인덱스 스캔 순서로 대체 → 소트 제거·부분 범위 처리","선택적으로 커버링 인덱스 구성"],
e:"결합 인덱스 설계의 3원칙 — ① = 조건 먼저, ② 범위 조건 나중, ③ 정렬 순서와 맞추기 — 를 모두 언급해야 만점입니다."}
]});

EXAMS.push({title:"제2회 실전 모의고사",note:"옵티마이저 내부·인덱스 구조 · 심화",q:[

/* ============ 1과목 · 데이터 모델링의 이해 (10) ============ */
{n:1,s:1,q:"성능 데이터 모델링을 수행하는 시점으로 가장 바람직한 것은?",o:["분석·설계 단계부터 함께 고려한다","구현이 끝난 뒤 튜닝 단계에서만 고려한다","운영 중 장애가 발생한 뒤에 고려한다","테스트 단계에서만 고려한다"],a:0,e:"모델이 확정된 뒤에 성능 문제를 고치려면 비용이 기하급수적으로 커집니다. 정규화·반정규화·PK 순서는 설계 단계에서 함께 판단해야 합니다."},
{n:2,s:1,q:"컬럼 수가 많고 자주 조회되는 컬럼이 일부에 몰려 있는 대용량 테이블에 적용할 반정규화 기법은?",o:["테이블 수직 분할","테이블 수평 분할","컬럼 중복","관계 중복"],a:0,e:"자주 쓰는 컬럼만 남겨 로우 길이를 줄이면 한 블록에 담기는 행 수가 늘어 I/O가 줄어듭니다."},
{n:3,s:1,q:"주식별자(PK)의 컬럼 순서를 결정할 때 성능 관점에서 가장 중요한 기준은?",o:["PK 인덱스를 자주 사용하는 SQL의 조건절에서 = 조건으로 쓰이는 컬럼을 앞에 둔다","컬럼 이름의 사전 순서","데이터 타입의 크기 순서","업무상 중요도 순서"],a:0,e:"PK를 만들면 유니크 인덱스가 함께 생기므로, 그 인덱스를 실제로 어떻게 액세스하는지가 순서를 결정합니다."},
{n:4,s:1,q:"슈퍼타입·서브타입 모델을 하나의 테이블로 통합(All in One)하는 방식이 유리한 경우는?",o:["대부분의 트랜잭션이 슈퍼타입 전체를 대상으로 하고 서브타입 구분 없이 조회할 때","서브타입별로 처리 트랜잭션이 완전히 분리되어 있을 때","서브타입마다 속성이 매우 많아 NULL이 대량 발생할 때","서브타입별 데이터량 차이가 극심할 때"],a:0,e:"전체 조회가 많으면 통합이 유리하고, 서브타입별 처리가 분리되어 있으면 분리 방식이 유리합니다."},
{n:5,s:1,q:"분산 데이터베이스 설계에서 테이블 위치를 결정할 때 가장 중요한 기준은?",o:["해당 테이블을 사용하는 트랜잭션의 발생 위치와 빈도","테이블의 컬럼 수","테이블 생성 순서","제약조건의 개수"],a:0,e:"원격 조인이 반복되면 네트워크 비용이 급증하므로, 함께 쓰이는 데이터는 같은 노드에 두는 것이 원칙입니다."},
{n:6,s:1,q:"릴레이션에서 모든 결정자가 후보키가 아니라면 위배되는 정규형은?",o:["제2정규형","제3정규형","BCNF","제4정규형"],a:2,e:"BCNF는 '모든 결정자는 후보키'라는 조건을 요구하며, 3NF보다 강한 조건입니다."},
{n:7,s:1,q:"주식별자를 도출할 때의 기준으로 옳지 않은 것은?",o:["업무에서 자주 이용되는 속성을 선정한다","명칭·내역처럼 길이가 긴 속성은 피한다","복합 식별자의 경우 속성 수를 가능한 한 많이 포함시킨다","자주 변경되는 속성은 배제한다"],a:2,e:"복합 식별자의 속성 수가 많아지면 자식 테이블로 전파되는 컬럼이 늘어 조인과 인덱스가 무거워집니다. 최소성을 지켜야 합니다."},
{n:8,s:1,q:"관계의 선택 사양(Optionality)이 '선택'이라는 것의 의미는?",o:["관계에 참여하지 않는 인스턴스가 존재할 수 있어 외래키에 NULL이 허용된다","항상 관계에 참여해야 한다","관계가 1:1임을 뜻한다","외래키가 존재하지 않는다"],a:0,e:"필수 관계는 반드시 참여해야 하므로 외래키가 NOT NULL이 되고, 선택 관계는 NULL이 허용되어 아우터 조인이 필요해질 수 있습니다."},
{n:9,s:1,q:"이력 테이블에서 특정 시점 데이터 조회 성능을 높이기 위한 설계로 가장 효과적인 것은?",o:["선분 이력으로 구성하고 (기준키, 종료일자 또는 시작일자) 순서의 인덱스를 둔다","점 이력으로만 구성한다","이력 테이블을 정규화만 강화한다","모든 컬럼에 개별 인덱스를 만든다"],a:0,e:"선분 이력은 BETWEEN 한 번으로 시점 조회가 가능하고, 인덱스로 대상 구간을 바로 찾을 수 있습니다."},
{n:10,s:1,q:"대량 데이터를 기간 단위로 나누어 저장·관리하며 조회 시 필요한 구간만 읽도록 하는 물리 설계 기법은?",o:["파티셔닝","클러스터링","비정규화","머티리얼라이즈드 뷰"],a:0,e:"레인지 파티셔닝과 파티션 프루닝을 함께 쓰면 오래된 데이터를 건드리지 않고 조회할 수 있습니다."},

/* ============ 2과목 · SQL 기본 및 활용 (20) ============ */
{n:11,s:2,q:"ANSI 표준 조인에서 조인 조건을 기술하는 절은?",o:["ON","WHERE","HAVING","USING만 가능"],a:0,e:"INNER JOIN ... ON 조건 형태로 쓰며, 조인 컬럼 이름이 같으면 USING (컬럼) 으로 축약할 수 있습니다."},
{n:12,s:2,q:"NATURAL JOIN에 대한 설명으로 옳은 것은?",o:["두 테이블의 이름과 타입이 같은 모든 컬럼을 자동으로 조인 조건에 사용한다","ON절을 반드시 함께 써야 한다","조인 컬럼에 테이블 별칭을 붙여야 한다","항상 카티션 프로덕트가 발생한다"],a:0,e:"의도하지 않은 동명 컬럼까지 조인 조건에 들어갈 수 있어 실무에서는 잘 쓰지 않습니다."},
{n:13,s:2,q:"LEFT OUTER JOIN에서 우측 테이블에 대한 필터 조건을 WHERE절에 두었을 때의 결과는?",o:["아우터 조인이 사실상 이너 조인처럼 동작한다","결과가 변하지 않는다","항상 에러가 발생한다","좌측 테이블 행이 늘어난다"],a:0,e:"WHERE는 조인 결과에 적용되므로 NULL로 채워진 행이 걸러집니다. 아우터 대상 조건은 ON절에 두어야 합니다."},
{n:14,s:2,q:"여러 컬럼을 한 번에 비교하는 다중 컬럼 서브쿼리의 예로 옳은 것은?",o:["WHERE (부서, 직급) IN (SELECT 부서, 직급 FROM 대상)","WHERE 부서 IN (SELECT 부서, 직급 FROM 대상)","WHERE 부서 = (SELECT 부서, 직급 FROM 대상)","WHERE EXISTS (부서, 직급)"],a:0,e:"좌변과 우변의 컬럼 개수와 순서가 일치해야 합니다."},
{n:15,s:2,q:"상관 서브쿼리(Correlated Subquery)의 특징으로 옳은 것은?",o:["메인 쿼리의 컬럼을 참조하므로 메인 쿼리 행마다 실행될 수 있다","메인 쿼리보다 항상 먼저 한 번만 실행된다","항상 조인으로 변환된다","FROM절에만 올 수 있다"],a:0,e:"옵티마이저가 Unnesting에 성공하면 조인으로 바뀌지만, 실패하면 행마다 반복 수행되어 부하가 커집니다."},
{n:16,s:2,q:"WITH절(CTE)을 사용하는 주된 이유로 가장 적절한 것은?",o:["반복되는 인라인 뷰에 이름을 붙여 가독성을 높이고 재사용할 수 있다","항상 성능이 향상된다","임시 테이블이 반드시 생성된다","DDL을 대신할 수 있다"],a:0,e:"MATERIALIZE 힌트를 주면 임시 결과를 만들어 재사용하고, INLINE 힌트를 주면 매번 펼쳐집니다."},
{n:17,s:2,q:"윈도우 함수에서 '현재 행과 그 이전 2개 행'을 집계 범위로 지정하는 표현은?",o:["ROWS BETWEEN 2 PRECEDING AND CURRENT ROW","ROWS BETWEEN CURRENT ROW AND 2 FOLLOWING","RANGE BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW","ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING"],a:0,e:"ROWS는 물리적 행 수, RANGE는 값의 범위를 기준으로 윈도우를 정합니다."},
{n:18,s:2,q:"부서별 급여 합계를 각 사원 행에 함께 보여 주려 할 때 적절한 표현은?",o:["SUM(급여) OVER (PARTITION BY 부서)","SUM(급여) GROUP BY 부서","SUM(급여) HAVING 부서","SUM(급여) CONNECT BY 부서"],a:0,e:"GROUP BY는 행을 줄이지만 윈도우 함수는 행을 유지한 채 집계값을 덧붙입니다."},
{n:19,s:2,q:"전체 합계에 대한 각 행의 비율을 구하는 윈도우 함수는?",o:["RATIO_TO_REPORT","CUME_DIST","NTILE","PERCENT_RANK"],a:0,e:"CUME_DIST는 누적 분포, PERCENT_RANK는 상대 순위, NTILE은 지정한 개수의 그룹으로 나눕니다."},
{n:20,s:2,q:"필요한 소계 조합만 골라서 생성하는 GROUP BY 확장 구문은?",o:["GROUPING SETS","ROLLUP","CUBE","PARTITION BY"],a:0,e:"GROUPING SETS((A,B),(A),())처럼 원하는 조합만 지정할 수 있습니다."},
{n:21,s:2,q:"ORDER BY에서 NULL을 항상 마지막에 정렬하려면 사용하는 구문은?",o:["ORDER BY 컬럼 NULLS LAST","ORDER BY 컬럼 DESC","ORDER BY NVL(컬럼,0)만 가능","ORDER BY 컬럼 IS NULL"],a:0,e:"Oracle은 오름차순에서 NULL이 마지막, 내림차순에서 처음에 오는 것이 기본이며 NULLS FIRST/LAST로 바꿀 수 있습니다."},
{n:22,s:2,q:"그룹 내 여러 행의 문자열을 하나로 이어 붙이는 함수는?",o:["LISTAGG","CONCAT","STRAGG만 가능","GROUP_CONCAT(Oracle 표준)"],a:0,e:"LISTAGG(컬럼, ',') WITHIN GROUP (ORDER BY 컬럼) 형태로 사용합니다."},
{n:23,s:2,q:"정규식을 이용해 패턴 일치 여부를 판단하는 조건절 함수는?",o:["REGEXP_LIKE","REGEXP_REPLACE","REGEXP_SUBSTR","REGEXP_INSTR"],a:0,e:"REPLACE는 치환, SUBSTR은 추출, INSTR은 위치 반환입니다."},
{n:24,s:2,q:"날짜형 컬럼에 대해 '3개월 뒤'를 구하는 함수는?",o:["ADD_MONTHS(날짜, 3)","NEXT_DAY(날짜, 3)","LAST_DAY(날짜)","TRUNC(날짜, 'MM')"],a:0,e:"NEXT_DAY는 지정 요일의 다음 날짜, LAST_DAY는 그 달의 마지막 날, TRUNC는 절삭입니다."},
{n:25,s:2,q:"ROUND(1234.5678, -2)의 결과로 옳은 것은?",o:["1200","1234.57","1230","1000"],a:0,e:"음수 자릿수는 정수부에서 반올림합니다. -2는 백의 자리 기준이므로 1200이 됩니다."},
{n:26,s:2,q:"시퀀스(SEQUENCE)에 대한 설명으로 옳지 않은 것은?",o:["NEXTVAL을 호출하면 값이 증가한다","CURRVAL은 현재 세션에서 NEXTVAL을 한 번 이상 호출해야 사용할 수 있다","롤백하면 사용된 시퀀스 값이 되돌아온다","CACHE 설정으로 성능을 높일 수 있다"],a:2,e:"시퀀스는 트랜잭션과 무관하게 증가하므로 롤백해도 값이 복구되지 않아 번호에 공백이 생길 수 있습니다."},
{n:27,s:2,q:"제약조건에 대한 설명으로 옳지 않은 것은?",o:["PRIMARY KEY는 NOT NULL과 UNIQUE를 함께 만족한다","FOREIGN KEY는 부모 테이블의 기본키나 유니크키를 참조한다","CHECK 제약조건으로 값의 범위를 제한할 수 있다","UNIQUE 제약조건이 걸린 컬럼에는 NULL을 저장할 수 없다"],a:3,e:"UNIQUE는 중복만 금지하며 NULL은 여러 건 허용됩니다."},
{n:28,s:2,q:"뷰를 통해 DML을 수행할 수 없게 만드는 요소가 아닌 것은?",o:["DISTINCT","GROUP BY와 집계 함수","집합 연산자","단순 컬럼 목록"],a:3,e:"단순 SELECT 뷰는 갱신 가능합니다. 집계·DISTINCT·집합 연산·ROWNUM 등이 있으면 갱신할 수 없습니다."},
{n:29,s:2,q:"비트맵 인덱스가 유리한 컬럼의 특성은?",o:["distinct 값의 종류가 매우 적고 DML이 드문 컬럼","distinct 값이 매우 많은 컬럼","자주 갱신되는 컬럼","NULL이 전혀 없는 기본키 컬럼"],a:0,e:"성별·상태코드처럼 카디널리티가 낮은 컬럼에 적합하며, DML이 잦으면 락 경합이 심해집니다."},
{n:30,s:2,q:"WHERE UPPER(이름) = 'KIM' 조건에서 인덱스를 사용하려면 필요한 것은?",o:["UPPER(이름)에 대한 함수 기반 인덱스","이름 컬럼의 일반 인덱스","비트맵 인덱스","인덱스를 삭제"],a:0,e:"CREATE INDEX ix ON t (UPPER(이름)) 처럼 가공한 값 자체를 색인해야 합니다."},

/* ============ 3과목 · SQL 고급 활용 및 튜닝 (40 + 서술 2) ============ */
{n:31,s:3,q:"옵티마이저 모드 FIRST_ROWS_N 의 목표로 옳은 것은?",o:["처음 N건을 최대한 빨리 반환하도록 계획을 세운다","전체 결과를 가장 적은 자원으로 처리한다","항상 해시 조인을 선택한다","항상 풀 스캔을 선택한다"],a:0,e:"온라인 조회처럼 앞부분만 보여 주는 화면에 적합하며, ALL_ROWS는 전체 처리량 최적화가 목표입니다."},
{n:32,s:3,q:"선택도(Selectivity)와 카디널리티(Cardinality)의 관계로 옳은 것은?",o:["카디널리티 = 총 행 수 × 선택도","선택도 = 카디널리티 × 총 행 수","둘은 무관하다","선택도는 항상 1이다"],a:0,e:"선택도 추정이 틀리면 카디널리티가 어긋나고, 조인 순서와 액세스 방식 선택이 통째로 잘못됩니다."},
{n:33,s:3,q:"데이터 분포가 균일하지 않은 컬럼에서 옵티마이저의 카디널리티 추정을 돕는 통계는?",o:["히스토그램","블록 수","평균 로우 길이","인덱스 높이"],a:0,e:"빈도 히스토그램이나 높이 균형 히스토그램으로 편중된 값의 분포를 알려 줍니다."},
{n:34,s:3,q:"바인드 변수 사용 시 첫 실행의 바인드 값에 맞춰 계획이 굳어지는 현상은?",o:["바인드 변수 피킹(Bind Peeking)","커서 공유","적응적 실행 계획","동적 샘플링"],a:0,e:"편중된 데이터에서 문제가 되며, 적응적 커서 공유(ACS)로 완화합니다."},
{n:35,s:3,q:"실제 실행 통계를 확인하여 예상 행 수와 실제 행 수를 비교할 때 유용한 것은?",o:["DBMS_XPLAN.DISPLAY_CURSOR의 A-Rows / E-Rows 비교","EXPLAIN PLAN만 확인","테이블 정의서 확인","제약조건 조회"],a:0,e:"E-Rows와 A-Rows 차이가 크면 통계나 조건 추정이 잘못된 것이므로 그 지점부터 손봐야 합니다."},
{n:36,s:3,q:"SQL 성능을 판단할 때 응답 시간과 함께 우선적으로 봐야 할 지표는?",o:["논리적 읽기(Buffer Gets) 수","SQL 문장의 길이","테이블 개수","컬럼 개수"],a:0,e:"블록을 얼마나 많이 읽었는지가 액세스 경로의 효율을 직접 보여 줍니다."},
{n:37,s:3,q:"Physical Reads가 많고 Buffer Gets는 적은 SQL의 해석으로 가장 알맞은 것은?",o:["캐시에 없는 블록을 디스크에서 많이 읽고 있어 I/O 병목일 수 있다","이미 캐시된 블록만 읽고 있다","파싱이 문제이다","락 경합이 문제이다"],a:0,e:"Buffer Gets는 논리적 읽기, Physical Reads는 디스크 읽기입니다."},
{n:38,s:3,q:"인덱스 리프 블록 분할(Leaf Block Split)이 자주 발생하는 상황은?",o:["순차적으로 증가하지 않는 키 값을 대량으로 삽입할 때","조회만 수행할 때","인덱스를 삭제했을 때","풀 스캔만 수행할 때"],a:0,e:"중간에 값이 끼어들면 블록을 쪼개야 하며, 순차 증가 키는 오른쪽 끝에서만 분할이 일어나 부담이 적습니다."},
{n:39,s:3,q:"대량 삭제 후 인덱스에 빈 공간이 많아 스캔 효율이 떨어질 때의 조치는?",o:["인덱스를 재생성하거나 COALESCE/REBUILD로 정리한다","통계를 삭제한다","인덱스를 하나 더 만든다","커밋 주기를 늘린다"],a:0,e:"삭제된 엔트리 자리가 바로 반환되지 않으므로 블록 밀도가 낮아집니다. 다만 무분별한 리빌드는 권장되지 않습니다."},
{n:40,s:3,q:"인덱스 구성 테이블(IOT, Index Organized Table)의 특징으로 옳은 것은?",o:["테이블 데이터를 기본키 인덱스 구조 안에 저장해 테이블 랜덤 액세스를 없앤다","힙 구조로 저장한다","기본키가 없어도 만들 수 있다","항상 풀 스캔만 가능하다"],a:0,e:"기본키 조회가 압도적으로 많은 테이블에 유리하지만, 보조 인덱스 액세스는 오히려 느려질 수 있습니다."},
{n:41,s:3,q:"ROWID에 대한 설명으로 옳은 것은?",o:["행의 물리적 위치 정보를 담고 있어 가장 빠른 단건 액세스 경로가 된다","행의 논리적 순번을 의미한다","행이 갱신되면 항상 변경된다","인덱스에는 저장되지 않는다"],a:0,e:"인덱스는 키 값과 ROWID를 저장하며, 이를 이용해 테이블 블록을 직접 찾아갑니다."},
{n:42,s:3,q:"인덱스 액세스 조건과 필터 조건의 차이로 옳은 것은?",o:["액세스 조건은 스캔 시작·종료 지점을 결정하고, 필터 조건은 읽은 뒤 걸러 낸다","둘은 같은 의미이다","필터 조건이 스캔 범위를 줄인다","액세스 조건은 테이블에만 적용된다"],a:0,e:"실행계획의 access와 filter 항목으로 구분해 확인할 수 있으며, 필터 조건이 많으면 헛읽기가 많다는 뜻입니다."},
{n:43,s:3,q:"결합 인덱스 (부서, 입사일) 에서 'WHERE 부서 BETWEEN :a AND :b AND 입사일 = :c' 조건의 문제점은?",o:["선두 컬럼이 범위 조건이라 입사일이 스캔 범위를 줄이지 못하고 필터로만 작동한다","인덱스를 아예 사용할 수 없다","항상 풀 스캔이 발생한다","입사일이 액세스 조건이 된다"],a:0,e:"범위 조건 뒤의 컬럼은 스캔 범위 축소에 기여하지 못합니다. (입사일, 부서) 순서가 더 효율적입니다."},
{n:44,s:3,q:"LIKE '%검색어' 형태의 조건이 인덱스를 사용할 수 없는 이유는?",o:["앞부분이 고정되지 않아 인덱스 스캔의 시작 지점을 정할 수 없기 때문","LIKE는 인덱스를 지원하지 않기 때문","문자열 타입이기 때문","와일드카드를 쓸 수 없기 때문"],a:0,e:"'검색어%' 처럼 앞이 고정되면 범위 스캔이 가능합니다. 뒷부분 검색이 필요하면 역순 컬럼이나 텍스트 인덱스를 검토합니다."},
{n:45,s:3,q:"WHERE A = :a OR B = :b 조건에서 A와 B에 각각 인덱스가 있을 때 옵티마이저가 선택할 수 있는 방식은?",o:["INDEX 결합(Concatenation) 또는 UNION ALL 분기","항상 풀 스캔만 가능","항상 해시 조인","항상 NL 조인"],a:0,e:"두 인덱스로 각각 읽고 결과를 결합할 수 있습니다. 중복 제거 비용을 고려해 UNION ALL로 직접 분기하기도 합니다."},
{n:46,s:3,q:"IS NULL 조건으로도 인덱스를 사용할 수 있게 만드는 방법은?",o:["NVL(컬럼,'-') 같은 함수 기반 인덱스나 상수를 결합한 복합 인덱스를 만든다","단일 컬럼 인덱스를 추가한다","비트맵 인덱스로는 불가능하다","통계를 재수집한다"],a:0,e:"단일 컬럼 B*Tree는 NULL을 저장하지 않지만, 상수를 추가한 복합 인덱스나 함수 기반 인덱스는 NULL도 색인합니다. 비트맵 인덱스도 NULL을 저장합니다."},
{n:47,s:3,q:"NL 조인에서 후행 테이블 액세스를 모아 처리해 랜덤 I/O를 줄이는 기능은?",o:["배치 I/O(Nested Loops Batching)","해시 조인","소트 머지 조인","파티션 와이즈 조인"],a:0,e:"ROWID를 모아 정렬한 뒤 한꺼번에 읽어 물리 I/O 효율을 높입니다."},
{n:48,s:3,q:"해시 조인에서 빌드 입력(Build Input)으로 선택해야 하는 집합은?",o:["결과 건수가 작은 쪽","결과 건수가 큰 쪽","인덱스가 있는 쪽","파티션된 쪽"],a:0,e:"작은 쪽으로 해시 테이블을 만들어야 메모리에 올라가고 디스크 사용을 피할 수 있습니다."},
{n:49,s:3,q:"EXISTS 서브쿼리가 조인으로 변환될 때 사용되는 조인 방식은?",o:["세미 조인(Semi Join)","안티 조인","아우터 조인","카티션 조인"],a:0,e:"NOT EXISTS는 안티 조인으로 변환됩니다. 세미 조인은 매칭되는 첫 행만 찾으면 되므로 중복 없이 처리됩니다."},
{n:50,s:3,q:"NOT IN 서브쿼리에 NULL이 포함될 수 있을 때 주의할 점은?",o:["결과가 공집합이 될 수 있으므로 NOT EXISTS나 NVL 처리로 바꾸는 것이 안전하다","성능만 느려질 뿐 결과는 같다","항상 에러가 발생한다","자동으로 안티 조인이 된다"],a:0,e:"NULL과의 비교는 UNKNOWN이 되어 NOT IN 전체가 참이 되지 못합니다."},
{n:51,s:3,q:"WITH절에 MATERIALIZE 힌트를 주었을 때의 동작은?",o:["임시 세그먼트에 결과를 만들어 두고 여러 번 참조할 때 재사용한다","매번 인라인으로 펼쳐 실행한다","인덱스를 생성한다","통계를 수집한다"],a:0,e:"여러 번 참조되고 결과가 작을 때 유리하지만, 임시 공간 쓰기 비용이 있어 한 번만 쓰면 손해입니다."},
{n:52,s:3,q:"조인 대상 테이블이 같은 기준으로 파티셔닝되어 있을 때 파티션 단위로 나누어 조인하는 방식은?",o:["파티션 와이즈 조인","브로드캐스트 조인","카티션 조인","세미 조인"],a:0,e:"각 파티션 쌍끼리 독립적으로 조인하므로 병렬 처리 효율이 크게 올라갑니다."},
{n:53,s:3,q:"병렬 DML을 사용하기 위해 세션에서 먼저 수행해야 하는 것은?",o:["ALTER SESSION ENABLE PARALLEL DML","COMMIT","통계 수집","인덱스 리빌드"],a:0,e:"병렬 질의와 달리 병렬 DML은 세션 수준에서 명시적으로 활성화해야 합니다."},
{n:54,s:3,q:"NOLOGGING 옵션과 함께 다이렉트 경로 적재를 수행할 때의 효과와 위험은?",o:["리두 생성이 줄어 빠르지만 미디어 복구가 불가능해질 수 있어 적재 후 백업이 필요하다","리두가 늘어난다","항상 안전하다","롤백이 빨라진다"],a:0,e:"NOLOGGING은 복구 관점의 위험을 동반하므로 운영 정책과 함께 판단해야 합니다."},
{n:55,s:3,q:"인덱스가 많은 테이블에 대량 INSERT를 수행할 때 유효한 전략은?",o:["인덱스를 UNUSABLE로 만들고 적재 후 재생성한다","인덱스를 더 추가한다","커밋을 건건이 수행한다","트리거를 추가한다"],a:0,e:"인덱스마다 유지 비용이 발생하므로 대량 적재 시에는 사후 생성이 유리한 경우가 많습니다."},
{n:56,s:3,q:"수백만 건을 UPDATE해야 할 때 권장되는 접근으로 옳지 않은 것은?",o:["한 건씩 반복하며 매번 커밋한다","적절한 단위로 나누어 처리하고 구간별로 커밋한다","조건에 맞는 인덱스로 대상 행을 빠르게 찾는다","가능하면 MERGE나 CTAS 후 교체를 검토한다"],a:0,e:"건별 처리와 잦은 커밋은 Call 부하와 로그 파일 동기화 대기를 폭증시킵니다."},
{n:57,s:3,q:"PL/SQL에서 컨텍스트 스위칭을 줄여 대량 처리 성능을 높이는 구문은?",o:["BULK COLLECT와 FORALL","CURSOR FOR LOOP","단건 INSERT 반복","IF-THEN-ELSE"],a:0,e:"SQL 엔진과 PL/SQL 엔진 사이를 오가는 횟수를 줄여 성능을 크게 개선합니다."},
{n:58,s:3,q:"장시간 실행되는 조회 중 ORA-01555(Snapshot too old)가 발생하는 원인은?",o:["읽기 일관성을 위해 필요한 언두 데이터가 이미 덮어써졌기 때문","인덱스가 없기 때문","락이 걸렸기 때문","통계가 오래되었기 때문"],a:0,e:"언두 보존 기간과 크기를 늘리거나, 조회 중 잦은 커밋으로 언두를 재사용하게 만드는 패턴을 피해야 합니다."},
{n:59,s:3,q:"힌트를 주었는데도 무시되는 경우로 가장 흔한 것은?",o:["힌트가 문법적으로 잘못되었거나 해당 계획이 불가능한 경우","통계가 최신인 경우","인덱스가 존재하는 경우","테이블이 작은 경우"],a:0,e:"힌트 오타, 잘못된 별칭 사용, 물리적으로 불가능한 조합이면 조용히 무시됩니다."},
{n:60,s:3,q:"검증된 실행 계획을 등록해 두고 계획이 바뀌는 것을 막는 기능은?",o:["SQL Plan Baseline","SQL Trace","AWR 보고서","동적 샘플링"],a:0,e:"통계 변화나 버전 업그레이드로 계획이 나빠지는 것을 방지합니다."},
{n:61,s:3,q:"통계 수집 전략으로 적절하지 않은 것은?",o:["데이터 변경이 큰 테이블만 주기적으로 수집한다","대량 적재 직후 해당 테이블 통계를 갱신한다","히스토그램이 필요한 컬럼을 식별해 수집한다","모든 테이블을 매 시간 전수 수집한다"],a:3,e:"전수 수집은 그 자체로 큰 부하이며, 변경량 기반 자동 수집과 대상 선별이 일반적입니다."},
{n:62,s:3,q:"동적 샘플링(Dynamic Sampling)이 사용되는 상황은?",o:["통계가 없거나 부족해 옵티마이저가 파싱 시점에 일부 블록을 읽어 추정할 때","항상 모든 SQL에서","힌트를 줄 때만","인덱스가 없을 때만"],a:0,e:"파싱 시간이 늘어나므로 정식 통계 수집이 우선입니다."},
{n:63,s:3,q:"동일 SQL이 반복 수행되는데 하드 파싱이 계속 발생한다면 우선 확인할 것은?",o:["리터럴 값을 그대로 넣고 있는지(바인드 변수 미사용)","인덱스 존재 여부","테이블 크기","커밋 주기"],a:0,e:"리터럴 SQL은 값마다 다른 문장으로 인식되어 매번 하드 파싱과 라이브러리 캐시 경합을 유발합니다."},
{n:64,s:3,q:"애플리케이션에서 한 번에 가져오는 행 수(Fetch Size)를 늘렸을 때의 효과는?",o:["네트워크 왕복 횟수가 줄어 대량 조회 성능이 향상된다","메모리 사용량이 줄어든다","항상 응답 시간이 나빠진다","파싱 횟수가 늘어난다"],a:0,e:"다만 지나치게 크면 클라이언트 메모리 부담과 첫 응답 지연이 커집니다."},
{n:65,s:3,q:"화면에 20건만 보여 주는데도 응답이 느리다면 가장 먼저 의심할 것은?",o:["소트나 전체 집계가 개입해 부분 범위 처리가 깨졌는지","네트워크 대역폭","화면 렌더링","DB 버전"],a:0,e:"ORDER BY, GROUP BY, DISTINCT, 집합 연산이 있으면 전체를 다 읽어야 합니다. 인덱스로 정렬을 대체하면 해결되는 경우가 많습니다."},
{n:66,s:3,q:"조인 순서를 잘못 선택해 성능이 나빠졌을 때 근본 원인으로 가장 흔한 것은?",o:["카디널리티 추정 오류(통계 부정확, 조건 상관관계 미반영)","인덱스가 너무 많음","커밋 주기가 짧음","컬럼 이름이 김"],a:0,e:"추정이 틀리면 작은 집합과 큰 집합의 판단이 뒤집혀 잘못된 순서가 선택됩니다."},
{n:67,s:3,q:"머티리얼라이즈드 뷰(Materialized View)의 특징으로 옳은 것은?",o:["결과를 실제로 저장해 두고 쿼리 재작성으로 자동 활용될 수 있다","일반 뷰와 동일하게 정의만 저장한다","항상 실시간 최신 데이터를 반환한다","인덱스를 만들 수 없다"],a:0,e:"집계 결과를 미리 만들어 두어 조회를 가속하며, 갱신 주기와 정합성 요구를 함께 고려해야 합니다."},
{n:68,s:3,q:"테이블 락과 행 락에 대한 설명으로 옳은 것은?",o:["일반 DML은 변경 대상 행에 배타 락을, 테이블에는 공유 성격의 락을 건다","DML은 항상 테이블 전체를 배타적으로 잠근다","SELECT는 항상 배타 락을 건다","락은 커밋과 무관하게 해제된다"],a:0,e:"행 단위 락 덕분에 서로 다른 행을 고치는 트랜잭션은 동시에 진행할 수 있으며, 락은 커밋·롤백 시 해제됩니다."},
{n:69,s:3,q:"SELECT ... FOR UPDATE 를 사용하는 목적은?",o:["조회한 행에 미리 락을 걸어 갱신 충돌을 방지한다","조회 성능을 높인다","정렬을 생략한다","통계를 갱신한다"],a:0,e:"낙관적 잠금과 달리 미리 잠그므로, NOWAIT나 SKIP LOCKED로 대기 정책을 함께 정하는 것이 좋습니다."},
{n:70,s:3,q:"다음 실행 계획에서 성능 문제로 가장 먼저 의심할 지점은?",code:"-------------------------------------------------------------------\n| Id | Operation                     | Name     | E-Rows | A-Rows |\n-------------------------------------------------------------------\n|  0 | SELECT STATEMENT              |          |        |     50 |\n|  1 |  NESTED LOOPS                 |          |     12 |     50 |\n|  2 |   TABLE ACCESS FULL           | 주문     |     10 | 800000 |\n|* 3 |   TABLE ACCESS BY INDEX ROWID | 고객     |      1 |     50 |\n-------------------------------------------------------------------",o:["주문 테이블의 E-Rows(10)와 A-Rows(800000) 차이가 커 카디널리티 추정이 크게 빗나갔다","고객 테이블의 인덱스가 없다","해시 조인을 써야 한다","정렬이 과도하다"],a:0,e:"추정 10건으로 보고 NL 조인과 풀 스캔을 골랐지만 실제로는 80만 건입니다. 통계와 조건 추정을 먼저 바로잡아야 하며, 이 상태라면 해시 조인이 적합할 가능성이 큽니다."},

{n:71,s:3,t:'desc',pts:15,q:"다음 SQL이 느리다. 원인으로 의심되는 점과 개선 방안을 서술하시오.",
code:"SELECT *\n  FROM 주문\n WHERE TO_CHAR(주문일자, 'YYYYMM') = '202608'\n   AND 고객번호 = :cust\n ORDER BY 주문일자 DESC;",
model:"① 원인 — 인덱스 컬럼인 주문일자를 TO_CHAR로 가공했기 때문에 주문일자 인덱스를 사용할 수 없고, 테이블 풀 스캔 후 필터링이 발생한다. 또한 SELECT *로 모든 컬럼을 읽어 불필요한 테이블 랜덤 액세스와 네트워크 전송이 늘어난다. ② 개선 — 조건을 컬럼 가공 없이 범위 조건으로 바꾼다. WHERE 주문일자 >= TO_DATE('20260801','YYYYMMDD') AND 주문일자 < TO_DATE('20260901','YYYYMMDD') 형태로 작성하면 인덱스 범위 스캔이 가능하다. ③ 인덱스는 등치 조건인 고객번호를 선두에 두고 범위·정렬 컬럼인 주문일자를 뒤에 둔 (고객번호, 주문일자)로 구성한다. 그러면 ORDER BY 주문일자 DESC를 인덱스 역순 스캔으로 대체해 소트를 제거하고 부분 범위 처리가 가능해진다. ④ SELECT *를 실제 필요한 컬럼으로 줄이고, 가능하면 해당 컬럼을 인덱스에 포함해 커버링 인덱스로 만든다.",
points:["컬럼 가공(TO_CHAR)으로 인한 인덱스 미사용","조건을 날짜 범위 비교로 변경","(고객번호, 주문일자) 결합 인덱스 구성","ORDER BY를 인덱스 스캔 순서로 대체해 소트 제거","SELECT * 축소 및 커버링 인덱스 검토"],
e:"'컬럼을 가공하지 말고 상수를 가공하라'가 핵심입니다. 인덱스 설계와 정렬 제거까지 함께 언급해야 만점입니다."},

{n:72,s:3,t:'desc',pts:15,q:"부분 범위 처리(Partial Range Scan)가 무엇인지 설명하고, 이를 깨뜨리는 요소와 유지하기 위한 방법을 서술하시오.",
model:"① 개념 — 조건을 만족하는 전체 결과를 모두 읽지 않고, 클라이언트가 요구하는 만큼만 읽어 즉시 반환한 뒤 필요할 때 이어서 읽는 처리 방식이다. 첫 응답 시간이 짧아 온라인 조회 화면에 적합하다. ② 깨뜨리는 요소 — ORDER BY로 인한 소트, GROUP BY나 집계 함수, DISTINCT, UNION 같은 중복 제거 집합 연산, 스칼라 서브쿼리를 제외한 전체 가공 작업은 결과 집합을 전부 만들어야 하므로 부분 범위 처리가 불가능해진다. ③ 유지 방법 — 정렬 순서와 일치하는 인덱스를 사용해 소트 오퍼레이션 자체를 없애고, UNION 대신 UNION ALL을 사용하며, 불필요한 DISTINCT를 제거한다. 페이징은 인라인 뷰에서 ROWNUM으로 조기 종료(Stop Key)시키고, 애플리케이션의 Fetch Size를 적절히 설정해 필요한 만큼만 가져온다.",
points:["전체를 읽지 않고 필요한 만큼만 읽어 반환하는 방식","첫 응답 시간이 짧아 온라인 조회에 유리","소트·집계·DISTINCT·UNION이 부분 범위 처리를 깨뜨림","인덱스로 소트를 대체하고 UNION ALL 사용","ROWNUM 조기 종료와 Fetch Size 조정"],
e:"'전체 범위를 읽게 만드는 연산이 무엇인가'를 정확히 나열하는 것이 채점 포인트입니다."}
]});

EXAMS.push({title:"제3회 실전 모의고사",note:"메모리 구조·파티션·옵티마이저 변환 · 고난도",q:[

/* ============ 1과목 · 데이터 모델링의 이해 (10) ============ */
{n:1,s:1,q:"속성의 분류에서 '파생 속성'에 해당하는 것은?",o:["회원의 생년월일","주문 건수의 합계","상품 코드","고객 이름"],a:1,e:"다른 속성으로부터 계산되어 만들어지는 값이 파생 속성입니다. 파생 속성은 정합성 유지 비용이 있어 저장 여부를 신중히 결정해야 합니다."},
{n:2,s:1,q:"도메인(Domain)에 대한 설명으로 옳은 것은?",o:["속성이 가질 수 있는 값의 범위와 데이터 타입을 정의한 것","엔터티 간의 관계를 뜻한다","테이블의 물리적 저장 위치이다","인덱스의 종류이다"],a:0,e:"도메인을 표준화하면 같은 의미의 속성이 서로 다른 타입·길이로 정의되는 것을 막을 수 있습니다."},
{n:3,s:1,q:"한 컬럼에 '서울,부산,대구'처럼 여러 값을 쉼표로 저장했다면 위배한 정규형은?",o:["제1정규형","제2정규형","제3정규형","BCNF"],a:0,e:"모든 속성 값이 원자값이어야 한다는 제1정규형 조건을 어긴 것입니다."},
{n:4,s:1,q:"반정규화 기법 중 '관계 반정규화'에 해당하는 것은?",o:["자주 조인하는 먼 엔터티 사이에 중복 관계(외래키)를 추가하는 것","테이블을 수직으로 분할하는 것","집계 컬럼을 추가하는 것","이력 테이블을 분리하는 것"],a:0,e:"조인 경로를 줄이기 위해 중복 관계를 두는 방식으로, 데이터 정합성 유지 부담이 생깁니다."},
{n:5,s:1,q:"식별자의 분류에서 '인조 식별자(대리키)'의 단점으로 옳은 것은?",o:["업무적 의미가 없어 중복 데이터를 걸러 내지 못하고 불필요한 인덱스가 생길 수 있다","조인이 복잡해진다","값이 자주 변경된다","NULL이 발생한다"],a:0,e:"본질 식별자에 유니크 제약을 별도로 걸지 않으면 논리적 중복이 들어올 수 있습니다."},
{n:6,s:1,q:"엔터티의 분류에서 '행위 엔터티'에 해당하는 것은?",o:["사원","부서","주문내역","상품"],a:2,e:"두 개 이상의 엔터티로부터 발생하며 수정이 잦은 것이 행위 엔터티입니다. 사원·부서·상품은 기본 엔터티에 가깝습니다."},
{n:7,s:1,q:"물리 모델링 단계에서 수행하는 작업으로 보기 어려운 것은?",o:["인덱스와 파티션 설계","저장 공간과 테이블스페이스 배치","반정규화 적용","업무 요구사항 수집"],a:3,e:"요구사항 수집은 요구조건 분석 단계의 작업입니다."},
{n:8,s:1,q:"1:1 관계로 도출된 두 엔터티를 하나로 통합할지 판단할 때 고려할 사항으로 옳은 것은?",o:["두 엔터티에 접근하는 트랜잭션의 패턴이 유사한지","컬럼 이름이 비슷한지","생성 순서가 어떤지","제약조건 개수가 같은지",],a:0,e:"항상 함께 조회된다면 통합이, 접근 빈도와 패턴이 크게 다르면 분리가 유리합니다."},
{n:9,s:1,q:"데이터 모델을 검증할 때 확인해야 할 항목으로 적절하지 않은 것은?",o:["엔터티의 식별자가 유일성과 최소성을 만족하는지","관계의 차수와 선택 사양이 업무와 맞는지","정규화 위반 여부와 반정규화의 근거가 있는지","SQL 문장의 실행 계획이 최적인지"],a:3,e:"실행 계획 검토는 구현 이후 튜닝 단계의 작업입니다."},
{n:10,s:1,q:"CAP 이론에서 분산 시스템이 동시에 만족할 수 없다고 보는 세 가지는?",o:["일관성, 가용성, 분할 내성","정규화, 무결성, 성능","원자성, 고립성, 지속성","확장성, 보안성, 이식성"],a:0,e:"네트워크 분할이 발생하는 상황에서는 일관성(C)과 가용성(A) 중 하나를 선택해야 한다는 것이 요지입니다."},

/* ============ 2과목 · SQL 기본 및 활용 (20) ============ */
{n:11,s:2,q:"연산에 NULL이 포함될 때의 결과로 옳은 것은?",o:["100 + NULL 의 결과는 NULL이다","100 + NULL 의 결과는 100이다","NULL = NULL 은 참이다","NULL은 0과 같다"],a:0,e:"NULL과의 산술 연산 결과는 NULL이며, 비교도 참이 되지 않습니다. IS NULL로 판단해야 합니다."},
{n:12,s:2,q:"숫자형 컬럼에 문자 상수를 비교했을 때 발생하는 일은?",o:["문자 상수가 숫자로 암시적 변환되며 변환 불가 값이 있으면 오류가 난다","항상 문자로 비교된다","비교가 무시된다","NULL이 반환된다"],a:0,e:"암시적 형변환은 예기치 못한 오류와 인덱스 미사용을 유발하므로 명시적으로 맞추는 것이 안전합니다."},
{n:13,s:2,q:"같은 테이블을 두 번 참조해 상하 관계를 조회하는 조인은?",o:["SELF JOIN","NATURAL JOIN","CROSS JOIN","FULL OUTER JOIN"],a:0,e:"사원과 관리자처럼 한 테이블 안에서 참조 관계가 있을 때 별칭을 달리해 조인합니다."},
{n:14,s:2,q:"스칼라 서브쿼리가 값을 찾지 못했을 때 반환하는 값은?",o:["NULL","0","공백 문자","오류"],a:0,e:"두 건 이상 반환되면 오류가 나지만, 없으면 NULL이 됩니다."},
{n:15,s:2,q:"'WHERE 급여 > ALL (SELECT 급여 FROM 사원 WHERE 부서=10)' 의 의미는?",o:["10번 부서의 최대 급여보다 큰 경우","10번 부서의 최소 급여보다 큰 경우","10번 부서의 평균보다 큰 경우","10번 부서에 속한 경우"],a:0,e:"> ALL은 모든 값보다 커야 하므로 최대값 초과, > ANY는 최소값 초과를 뜻합니다."},
{n:16,s:2,q:"ROWNUM의 특성으로 옳은 것은?",o:["결과 집합이 만들어지는 순서대로 1부터 부여되므로 'WHERE ROWNUM = 5' 는 결과가 없다","정렬 후에 부여된다","항상 원하는 순번을 가져올 수 있다","ORDER BY보다 나중에 평가된다"],a:0,e:"첫 행이 1이 되지 못하면 이후 행도 번호를 받지 못합니다. 인라인 뷰로 감싸 정렬한 뒤 사용해야 합니다."},
{n:17,s:2,q:"파티션 내에서 마지막 값을 가져올 때 프레임을 명시해야 하는 이유는?",o:["기본 프레임이 현재 행까지이므로 LAST_VALUE가 현재 행 값을 반환하기 때문","LAST_VALUE는 항상 NULL을 반환하기 때문","정렬이 무시되기 때문","성능 때문"],a:0,e:"ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING 을 명시해야 파티션 전체의 마지막 값을 얻습니다."},
{n:18,s:2,q:"계층형 질의에서 시작 조건을 지정하는 절과 부모 행을 참조하는 연산자로 옳은 것은?",o:["START WITH / PRIOR","CONNECT BY / LEVEL","WHERE / ROWNUM","GROUP BY / HAVING"],a:0,e:"START WITH로 루트를 정하고 CONNECT BY PRIOR 부모컬럼 = 자식컬럼 형태로 전개합니다."},
{n:19,s:2,q:"계층 구조에서 루트부터 현재 노드까지의 경로를 문자열로 만드는 함수는?",o:["SYS_CONNECT_BY_PATH","CONNECT_BY_ROOT","CONNECT_BY_ISLEAF","LEVEL"],a:0,e:"SYS_CONNECT_BY_PATH(컬럼, '/') 형태로 사용합니다."},
{n:20,s:2,q:"하나의 SELECT 결과를 조건에 따라 여러 테이블에 나누어 입력하는 구문은?",o:["INSERT ALL / INSERT FIRST","MERGE","UPDATE ... SET","CREATE TABLE AS SELECT"],a:0,e:"INSERT FIRST는 조건을 만족하는 첫 절에만, INSERT ALL은 조건을 만족하는 모든 절에 입력합니다."},
{n:21,s:2,q:"DELETE와 TRUNCATE의 차이로 옳지 않은 것은?",o:["DELETE는 조건을 줄 수 있고 롤백이 가능하다","TRUNCATE는 DDL이라 자동 커밋된다","TRUNCATE는 일반적으로 더 빠르고 HWM을 초기화한다","DELETE는 테이블 구조까지 삭제한다"],a:3,e:"테이블 구조까지 삭제하는 것은 DROP입니다."},
{n:22,s:2,q:"다른 사용자에게 받은 권한을 제3자에게 다시 부여할 수 있게 하는 옵션은?",o:["WITH GRANT OPTION","WITH ADMIN OPTION","CASCADE","PUBLIC"],a:0,e:"객체 권한은 WITH GRANT OPTION, 시스템 권한은 WITH ADMIN OPTION을 사용합니다."},
{n:23,s:2,q:"객체에 대한 별칭을 만들어 스키마 이름 없이 접근하게 해 주는 객체는?",o:["SYNONYM","VIEW","SEQUENCE","INDEX"],a:0,e:"PUBLIC SYNONYM으로 만들면 모든 사용자가 스키마 접두어 없이 접근할 수 있습니다."},
{n:24,s:2,q:"테이블과 컬럼, 인덱스 정보를 조회할 수 있는 것은?",o:["데이터 딕셔너리 뷰(USER_TABLES, USER_IND_COLUMNS 등)","임시 테이블","시퀀스","트리거"],a:0,e:"USER_, ALL_, DBA_ 접두어에 따라 조회 범위가 달라집니다."},
{n:25,s:2,q:"UNION과 UNION ALL의 결과가 동일해지는 경우는?",o:["두 집합에 중복 행이 전혀 없는 경우","항상 동일하다","정렬을 하지 않은 경우","컬럼 수가 다른 경우"],a:0,e:"중복이 없다면 결과는 같지만, UNION은 중복 제거를 위한 정렬·해시 부하를 여전히 부담합니다."},
{n:26,s:2,q:"NULL을 포함한 컬럼에 대해 COUNT와 SUM의 동작으로 옳은 것은?",o:["COUNT(컬럼)과 SUM(컬럼) 모두 NULL을 제외한다","COUNT(컬럼)만 NULL을 포함한다","SUM은 NULL을 0으로 계산한다","둘 다 NULL을 포함한다"],a:0,e:"집계 함수는 NULL을 무시하며, COUNT(*)만 전체 행을 셉니다."},
{n:27,s:2,q:"CASE 표현식에서 ELSE를 생략하고 어떤 조건에도 해당하지 않으면 반환되는 값은?",o:["NULL","0","공백","오류"],a:0,e:"의도치 않은 NULL이 집계에 영향을 주므로 ELSE를 명시하는 편이 안전합니다."},
{n:28,s:2,q:"인덱스가 자동으로 생성되는 제약조건의 조합으로 옳은 것은?",o:["PRIMARY KEY, UNIQUE","FOREIGN KEY, CHECK","NOT NULL, DEFAULT","CHECK, DEFAULT"],a:0,e:"외래키에는 인덱스가 자동 생성되지 않으므로, 부모 행 삭제나 조인 성능을 위해 직접 만들어 주는 것이 좋습니다."},
{n:29,s:2,q:"외래키 컬럼에 인덱스를 만들지 않았을 때 발생할 수 있는 문제는?",o:["부모 행 삭제·수정 시 자식 테이블 전체를 확인하면서 락 경합과 풀 스캔이 발생할 수 있다","외래키 제약이 무효가 된다","조인이 불가능해진다","NULL을 저장할 수 없다"],a:0,e:"자식 참조 확인을 위해 인덱스가 필요합니다."},
{n:30,s:2,q:"동일한 결과를 반환하지만 성능상 권장되지 않는 표현은?",o:["WHERE 부서 IN (SELECT 부서 FROM 부서목록) 대신 DISTINCT 조인으로 중복 제거","EXISTS 사용","조인 후 필요한 컬럼만 SELECT","인덱스를 활용한 범위 조건"],a:0,e:"DISTINCT로 중복을 사후 제거하면 불필요한 소트·해시 부하가 발생합니다. 세미 조인으로 처리하는 EXISTS/IN이 낫습니다."},

/* ============ 3과목 · SQL 고급 활용 및 튜닝 (40 + 서술 2) ============ */
{n:31,s:3,q:"SGA에 포함되지 않는 구성 요소는?",o:["버퍼 캐시","공유 풀(라이브러리 캐시)","리두 로그 버퍼","세션별 소트 영역(PGA)"],a:3,e:"정렬과 해시에 사용하는 작업 영역은 세션별 메모리인 PGA에 속합니다."},
{n:32,s:3,q:"버퍼 캐시 히트율이 높은데도 SQL이 느리다면 의심할 점은?",o:["논리적 읽기 자체가 과도해 비효율적인 액세스 경로를 쓰고 있을 수 있다","디스크가 고장 났다","네트워크가 느리다","통계가 최신이다"],a:0,e:"히트율은 캐시에서 읽은 비율일 뿐입니다. 같은 블록을 수없이 반복해 읽어도 히트율은 높게 나옵니다."},
{n:33,s:3,q:"라이브러리 캐시에서 발생하는 경합의 주요 원인은?",o:["바인드 변수를 쓰지 않아 유사한 SQL이 대량으로 파싱되는 경우","버퍼 캐시가 작은 경우","인덱스가 많은 경우","커밋이 드문 경우"],a:0,e:"하드 파싱이 몰리면 공유 풀 래치 경합이 발생합니다."},
{n:34,s:3,q:"'db file sequential read' 대기 이벤트가 주로 의미하는 것은?",o:["인덱스를 통한 단일 블록 랜덤 읽기","테이블 풀 스캔의 멀티블록 읽기","리두 로그 쓰기","락 대기"],a:0,e:"멀티블록 읽기는 'db file scattered read'입니다. 이름과 실제 동작이 반대로 느껴지는 대표적인 항목입니다."},
{n:35,s:3,q:"테이블 풀 스캔이 인덱스 스캔보다 유리한 이유 중 하나는?",o:["한 번에 여러 블록을 읽는 멀티블록 I/O를 사용하기 때문","랜덤 액세스를 많이 하기 때문","정렬이 보장되기 때문","캐시를 쓰지 않기 때문"],a:0,e:"순차적으로 대량을 읽을 때는 멀티블록 I/O가 훨씬 효율적입니다."},
{n:36,s:3,q:"테이블의 HWM(High Water Mark)에 대한 설명으로 옳은 것은?",o:["풀 스캔은 HWM 아래 블록을 모두 읽으므로 대량 삭제 후에도 스캔량이 줄지 않는다","DELETE 시 자동으로 낮아진다","인덱스에만 존재한다","커밋 시 초기화된다"],a:0,e:"DELETE로는 내려가지 않고 TRUNCATE나 테이블 재구성(MOVE/shrink)으로 정리해야 합니다."},
{n:37,s:3,q:"UPDATE로 로우 길이가 늘어나 원래 블록에 담기지 못하고 다른 블록으로 옮겨지는 현상은?",o:["행 이주(Row Migration)","행 연결(Row Chaining)","블록 분할","클러스터링"],a:0,e:"행 연결은 처음부터 한 블록에 담기지 않을 만큼 큰 행에서 발생합니다. 이주는 PCTFREE를 늘려 예방합니다."},
{n:38,s:3,q:"PCTFREE를 크게 설정했을 때의 효과로 옳은 것은?",o:["갱신을 위한 여유 공간이 늘어 행 이주가 줄지만 블록당 저장 행 수는 감소한다","블록당 저장 행 수가 늘어난다","인덱스가 작아진다","리두가 줄어든다"],a:0,e:"갱신이 잦은 테이블은 크게, 조회 위주 테이블은 작게 잡습니다."},
{n:39,s:3,q:"인덱스의 클러스터링 팩터를 개선하는 가장 근본적인 방법은?",o:["인덱스 키 순서에 맞춰 테이블 데이터를 재정렬(재구성)한다","인덱스를 리빌드한다","통계를 재수집한다","힌트를 추가한다"],a:0,e:"클러스터링 팩터는 테이블의 물리적 저장 순서에 좌우되므로 인덱스만 리빌드해서는 개선되지 않습니다."},
{n:40,s:3,q:"선두 컬럼의 중복 값이 많은 결합 인덱스에서 저장 공간을 줄이는 기능은?",o:["인덱스 키 압축(Key Compression)","리버스 키 인덱스","비트맵 인덱스","함수 기반 인덱스"],a:0,e:"반복되는 선두 컬럼 값을 접두어로 분리해 한 번만 저장합니다."},
{n:41,s:3,q:"순차적으로 증가하는 키로 인한 인덱스 우측 끝 블록 경합을 완화하는 인덱스는?",o:["리버스 키 인덱스","비트맵 인덱스","IOT","클러스터 인덱스"],a:0,e:"키를 뒤집어 저장해 삽입 위치를 분산합니다. 다만 범위 스캔이 불가능해집니다."},
{n:42,s:3,q:"로컬 파티션 인덱스와 글로벌 파티션 인덱스의 차이로 옳은 것은?",o:["로컬 인덱스는 테이블 파티션과 1:1로 대응해 파티션 관리 작업 시 유지보수가 쉽다","글로벌 인덱스가 항상 더 빠르다","로컬 인덱스는 파티션 키를 포함해야만 한다","글로벌 인덱스는 파티션할 수 없다"],a:0,e:"파티션 추가·삭제 시 로컬 인덱스는 해당 파티션만 영향을 받지만, 글로벌 인덱스는 전체가 무효화될 수 있습니다."},
{n:43,s:3,q:"대량 데이터를 파티션 단위로 순식간에 교체해 적재하는 기법은?",o:["EXCHANGE PARTITION","MERGE PARTITION","SPLIT PARTITION","TRUNCATE PARTITION"],a:0,e:"임시 테이블에 데이터를 만들어 두고 딕셔너리 정보만 교환하므로 거의 즉시 완료됩니다."},
{n:44,s:3,q:"레인지 파티션 안에서 다시 해시로 나누어 병렬 처리 효율을 높이는 구성은?",o:["컴포지트 파티셔닝(Range-Hash)","리스트 파티셔닝","시스템 파티셔닝","인터벌 파티셔닝"],a:0,e:"기간으로 나누고 그 안에서 균등 분산하여 파티션 프루닝과 병렬성을 함께 얻습니다."},
{n:45,s:3,q:"병렬 조인에서 한쪽 집합이 매우 작을 때 사용되는 데이터 분배 방식은?",o:["브로드캐스트(Broadcast) 분배","해시 분배","레인지 분배","라운드 로빈 분배"],a:0,e:"작은 집합을 모든 병렬 프로세스에 복제해 재분배 비용을 줄입니다."},
{n:46,s:3,q:"스타 스키마에서 팩트 테이블과 여러 차원 테이블을 효율적으로 조인하기 위한 변환은?",o:["스타 변환(Star Transformation)","뷰 머징","조건절 푸싱","OR-Expansion"],a:0,e:"차원 테이블 조건으로 비트맵 인덱스를 이용해 팩트 테이블의 대상 행을 먼저 좁힙니다."},
{n:47,s:3,q:"외래키 제약이 있고 자식 테이블 컬럼만 조회할 때 부모 테이블 조인을 생략하는 옵티마이저 변환은?",o:["조인 제거(Join Elimination)","뷰 머징","서브쿼리 언네스팅","조건절 이행"],a:0,e:"참조 무결성이 보장되므로 조인해도 결과가 달라지지 않는다는 것을 알고 생략합니다."},
{n:48,s:3,q:"'A = B AND B = 10' 조건에서 'A = 10' 을 추가로 유도하는 옵티마이저 기능은?",o:["조건절 이행(Transitive Predicate Generation)","조건절 푸싱","뷰 머징","조인 제거"],a:0,e:"추가된 조건으로 A 컬럼의 인덱스를 사용할 수 있게 되어 액세스 경로가 넓어집니다."},
{n:49,s:3,q:"OR 조건을 UNION ALL 분기로 바꾸어 각각 인덱스를 사용하게 만드는 변환은?",o:["OR-Expansion","OR-Compression","서브쿼리 팩토링","조인 제거"],a:0,e:"USE_CONCAT 힌트로 유도하거나 직접 UNION ALL로 작성합니다."},
{n:50,s:3,q:"인라인 뷰가 머징되지 않도록 강제하는 힌트는?",o:["NO_MERGE","MERGE","PUSH_PRED","UNNEST"],a:0,e:"뷰를 먼저 독립적으로 처리하게 하고 싶을 때 사용합니다."},
{n:51,s:3,q:"뷰 안쪽으로 조인 조건을 밀어 넣도록 유도하는 힌트는?",o:["PUSH_PRED","NO_MERGE","MATERIALIZE","ORDERED"],a:0,e:"조인 조건이 뷰 내부에서 인덱스 액세스 조건으로 쓰이게 되어 중간 집합이 크게 줄어듭니다."},
{n:52,s:3,q:"인덱스를 내림차순으로 스캔해 ORDER BY DESC의 정렬을 생략하도록 하는 힌트는?",o:["INDEX_DESC","INDEX_ASC","INDEX_FFS","INDEX_SS"],a:0,e:"인덱스가 오름차순으로 저장되어 있어도 역순 스캔이 가능합니다."},
{n:53,s:3,q:"PL/SQL 함수를 SELECT절에서 행마다 호출할 때 발생하는 부하를 줄이는 방법으로 적절하지 않은 것은?",o:["함수를 조인이나 스칼라 서브쿼리로 대체한다","DETERMINISTIC을 선언해 캐싱 효과를 노린다","결과를 미리 계산해 컬럼으로 보관한다","함수 내부에서 커밋을 수행한다"],a:3,e:"함수 내부 커밋은 트랜잭션 일관성을 깨뜨리며 성능 문제도 해결하지 못합니다."},
{n:54,s:3,q:"소트 작업이 PGA 메모리를 초과했을 때 발생하는 일은?",o:["임시 테이블스페이스에 기록하는 디스크 소트가 발생해 성능이 크게 저하된다","자동으로 인덱스를 생성한다","소트가 생략된다","오류가 발생한다"],a:0,e:"실행 계획에서 소트 오퍼레이션의 Used-Tmp 값으로 확인할 수 있습니다."},
{n:55,s:3,q:"대량 데이터를 새 구조로 옮기며 정렬된 상태로 저장해 클러스터링 팩터까지 개선하는 방법은?",o:["CTAS(CREATE TABLE AS SELECT ... ORDER BY) 후 인덱스 재생성","DELETE 후 INSERT","인덱스 리빌드만 수행","통계만 재수집"],a:0,e:"물리적 저장 순서를 원하는 인덱스 키 순서와 맞출 수 있습니다."},
{n:56,s:3,q:"세션별로 독립적인 데이터를 갖고 트랜잭션이나 세션 종료 시 자동으로 비워지는 객체는?",o:["글로벌 임시 테이블(GTT)","일반 테이블","뷰","시퀀스"],a:0,e:"중간 결과를 여러 번 재사용해야 할 때 유용하며 리두 생성이 적습니다."},
{n:57,s:3,q:"운영 중 서비스 중단 없이 인덱스를 생성하려면 사용해야 하는 옵션은?",o:["ONLINE","NOLOGGING","PARALLEL","COMPRESS"],a:0,e:"CREATE INDEX ... ONLINE은 DML을 막지 않지만 소요 시간은 더 길어집니다."},
{n:58,s:3,q:"자주 수행되는 집계 결과를 미리 저장해 두고 옵티마이저가 자동으로 활용하게 하는 기능은?",o:["머티리얼라이즈드 뷰와 쿼리 재작성(Query Rewrite)","일반 뷰","시노님","시퀀스"],a:0,e:"원본을 조회하는 SQL도 옵티마이저가 MV로 바꿔 처리할 수 있습니다."},
{n:59,s:3,q:"데드락(Deadlock)이 발생했을 때 DBMS의 일반적인 처리 방식은?",o:["한쪽 트랜잭션을 강제로 실패시켜 교착 상태를 해소한다","두 트랜잭션 모두 커밋한다","무한 대기한다","테이블을 잠근다"],a:0,e:"애플리케이션에서 자원 접근 순서를 통일하면 데드락을 예방할 수 있습니다."},
{n:60,s:3,q:"읽기 일관성(Read Consistency)을 제공하기 위해 사용되는 것은?",o:["언두(Undo) 데이터","리두 로그","임시 테이블스페이스","버퍼 캐시만"],a:0,e:"질의 시작 시점의 SCN 기준으로 변경 전 이미지를 언두에서 읽어 일관된 결과를 만듭니다."},
{n:61,s:3,q:"성능 문제 분석을 위해 특정 시간대의 대기 이벤트와 부하 상위 SQL을 확인할 때 사용하는 보고서는?",o:["AWR / ASH 보고서","EXPLAIN PLAN","데이터 딕셔너리 정의서","제약조건 목록"],a:0,e:"AWR은 스냅샷 구간의 통계를, ASH는 세션 상태 샘플을 제공합니다."},
{n:62,s:3,q:"SQL 튜닝 시 가장 먼저 확인해야 할 순서로 적절한 것은?",o:["문제 SQL 식별 → 실행 계획과 실제 통계 확인 → 병목 지점 파악 → 액세스 경로 개선","인덱스 추가 → 힌트 적용 → 통계 수집","힌트 적용 → 실행 계획 확인","테이블 재구성 → SQL 수정"],a:0,e:"측정 없이 인덱스나 힌트부터 손대면 부작용만 남습니다."},
{n:63,s:3,q:"인덱스를 무분별하게 추가했을 때 발생하는 부작용으로 옳은 것은?",o:["INSERT·UPDATE·DELETE마다 인덱스 유지 비용이 늘고 저장 공간과 옵티마이저 선택 혼란이 커진다","조회 성능만 좋아진다","저장 공간이 줄어든다","락 경합이 사라진다"],a:0,e:"인덱스는 조회를 위한 것이지만 DML에는 순수한 비용입니다."},
{n:64,s:3,q:"파티션 프루닝이 동작하지 않는 원인으로 가장 흔한 것은?",o:["조건절에서 파티션 키를 가공했거나 바인드 값으로 판단이 지연된 경우","인덱스가 많은 경우","통계가 최신인 경우","병렬도를 높인 경우"],a:0,e:"파티션 키 컬럼을 함수로 감싸면 프루닝이 되지 않습니다."},
{n:65,s:3,q:"조인 순서를 FROM절에 적은 순서대로 고정하는 힌트는?",o:["ORDERED","LEADING","USE_NL","INDEX"],a:0,e:"LEADING은 선행 테이블을 직접 지정하고, ORDERED는 FROM절 순서를 그대로 따릅니다."},
{n:66,s:3,q:"NL 조인에서 후행 테이블에 인덱스가 없을 때 나타나는 현상은?",o:["선행 집합의 행마다 후행 테이블을 풀 스캔해 성능이 급격히 나빠진다","자동으로 해시 조인으로 바뀐다","조인이 실패한다","정렬이 발생한다"],a:0,e:"이런 경우 해시 조인이나 소트 머지 조인이 대안이 됩니다."},
{n:67,s:3,q:"스칼라 서브쿼리를 아우터 조인으로 바꾸는 것이 유리한 상황은?",o:["입력 값의 종류가 많아 캐싱 효과를 기대할 수 없고 호출 횟수가 매우 많은 경우","입력 값의 종류가 적은 경우","결과가 항상 한 건인 경우","조인 컬럼이 없는 경우"],a:0,e:"캐시 적중률이 낮으면 행마다 서브쿼리를 수행하므로 조인으로 한 번에 처리하는 편이 낫습니다."},
{n:68,s:3,q:"인덱스만 읽고 테이블 액세스를 하지 않는 실행 계획에서 나타나는 오퍼레이션은?",o:["INDEX RANGE SCAN 뒤에 TABLE ACCESS 단계가 없음","TABLE ACCESS FULL","INDEX UNIQUE SCAN 뒤 TABLE ACCESS BY INDEX ROWID","NESTED LOOPS"],a:0,e:"필요한 컬럼이 모두 인덱스에 있는 커버링 인덱스 상황입니다."},
{n:69,s:3,q:"다음 두 SQL 중 인덱스 (지역, 등록일) 를 더 효율적으로 사용하는 것은?",code:"(1) WHERE 지역 = '서울' AND 등록일 >= :dt\n(2) WHERE 지역 LIKE '서%'  AND 등록일 >= :dt",o:["(1) — 선두 컬럼이 등치 조건이라 스캔 시작·종료점이 확정된다","(2) — LIKE가 더 넓은 범위를 커버한다","두 SQL의 효율은 동일하다","둘 다 인덱스를 사용할 수 없다"],a:0,e:"(2)는 선두 컬럼이 범위 조건이라 등록일 조건이 스캔 범위를 좁히지 못하고 필터로만 작동합니다."},
{n:70,s:3,q:"다음 실행 계획에서 개선 방향으로 가장 적절한 것은?",code:"---------------------------------------------------------------\n| Id | Operation                | Name       | A-Rows | Buffers |\n---------------------------------------------------------------\n|  0 | SELECT STATEMENT         |            |     20 |  482000 |\n|  1 |  SORT ORDER BY           |            |     20 |  482000 |\n|  2 |   TABLE ACCESS BY INDEX  | 주문       | 300000 |  482000 |\n|* 3 |    INDEX RANGE SCAN      | 주문_고객  | 300000 |    1200 |\n---------------------------------------------------------------",o:["정렬 순서와 맞는 인덱스로 소트를 제거하고 상위 20건만 읽도록 부분 범위 처리를 유도한다","인덱스를 삭제한다","병렬도를 높인다","커밋 주기를 늘린다"],a:0,e:"20건만 필요한데 30만 건을 읽고 정렬했습니다. Buffers의 대부분이 테이블 랜덤 액세스에서 발생했으므로, (고객, 정렬컬럼) 인덱스로 소트를 없애면 필요한 만큼만 읽고 멈출 수 있습니다."},

{n:71,s:3,t:'desc',pts:15,q:"동일한 SQL이 평소에는 빠른데 특정 시간대에만 크게 느려진다. 원인을 세 가지 이상 들고 각각의 확인 방법을 서술하시오.",
model:"① 실행 계획 변경 — 통계 재수집이나 바인드 변수 피킹으로 계획이 바뀌었을 수 있다. DBMS_XPLAN.DISPLAY_CURSOR로 같은 SQL_ID의 여러 child cursor 계획을 비교하고, SQL Plan Baseline으로 계획을 고정한다. ② 동시성과 락 경합 — 배치 작업이 같은 시간대에 대량 DML을 수행하며 행 락이나 TX 대기를 유발할 수 있다. ASH/AWR에서 해당 시간대의 대기 이벤트(enq: TX - row lock contention 등)를 확인한다. ③ 자원 경합 — CPU 포화, I/O 부하, PGA 부족으로 인한 디스크 소트가 발생할 수 있다. AWR의 Top Wait Events와 실행 계획의 Used-Tmp를 확인한다. ④ 데이터량 변화 — 특정 시간대에 대상 데이터가 급증해 카디널리티가 달라졌을 수 있다. A-Rows와 E-Rows를 비교한다. ⑤ 캐시 상태 — 야간 배치가 버퍼 캐시를 밀어내 물리 I/O가 늘었을 수 있다. Buffer Gets 대비 Physical Reads 비율을 본다.",
points:["실행 계획 변경(통계·바인드 피킹) → DISPLAY_CURSOR 비교, Plan Baseline","락 경합 → ASH/AWR 대기 이벤트 확인","자원 경합(CPU·I/O·PGA) → Top Wait Events, Used-Tmp","데이터량 변화 → E-Rows와 A-Rows 비교","버퍼 캐시 상태 → Physical Reads 비율"],
e:"'SQL은 그대로인데 환경이 변했다'는 관점으로 접근해야 합니다. 원인마다 확인 도구를 짝지어 답해야 점수가 나옵니다."},

{n:72,s:3,t:'desc',pts:15,q:"대량 데이터가 쌓이는 주문 테이블의 조회 성능을 개선하기 위해 파티셔닝을 검토하고 있다. 파티셔닝 방식 선택 기준과 기대 효과, 주의할 점을 서술하시오.",
model:"① 방식 선택 — 주문일자처럼 연속된 값으로 조회 조건이 걸리고 기간별 보관·삭제가 필요하면 레인지 파티셔닝이 적합하다. 지역코드나 상태코드처럼 값의 종류가 정해져 있으면 리스트, 특정 키로 균등 분산이 목적이면 해시를 쓴다. 기간으로 나눈 뒤 그 안에서 병렬성을 얻으려면 Range-Hash 컴포지트를 검토한다. ② 기대 효과 — 조건절에 파티션 키가 있으면 파티션 프루닝으로 불필요한 구간을 읽지 않아 I/O가 크게 준다. 오래된 데이터는 파티션 단위로 TRUNCATE나 DROP 하여 순식간에 정리할 수 있고, EXCHANGE PARTITION으로 대량 적재도 즉시 처리된다. 파티션 와이즈 조인과 병렬 처리 효율도 높아진다. ③ 주의할 점 — 조건절에 파티션 키가 없으면 모든 파티션을 읽게 되어 효과가 사라지고, 파티션 키를 함수로 가공해도 프루닝이 되지 않는다. 인덱스는 로컬로 구성해야 파티션 관리 시 유지보수가 쉬우며, 글로벌 인덱스는 파티션 DDL로 무효화될 수 있다. 파티션이 지나치게 많으면 관리 부담과 파싱 비용이 늘어난다.",
points:["조회 조건과 보관 정책에 따른 방식 선택(Range/List/Hash/Composite)","파티션 프루닝으로 I/O 감소","파티션 단위 삭제·교체로 관리 비용 절감","조건절에 파티션 키가 없거나 가공하면 효과 상실","로컬 인덱스 우선, 글로벌 인덱스 무효화 주의"],
e:"'무엇을 기준으로 나눌지'와 '조건절에 그 키가 실제로 들어오는지'가 핵심입니다. 관리 측면의 이점까지 언급하면 좋습니다."}
]});
